def _plan_payload(command: str = "printf hello", cwd: str = ".") -> dict[str, Any]:
    return {
        "summary": "Run one command.",
        "tasks": [
            {
                "task_id": "task_1",
                "goal": "Run a command",
                "semantic_verb": "execute",
                "object_type": "shell",
                "dependencies": [],
                "reason": "The user requested command execution.",
            }
        ],
        "actions": [
            {
                "action_id": "action_1",
                "task_id": "task_1",
                "kind": "shell_command",
                "command": command,
                "cwd": cwd,
                "inputs": {},
                "declared_output_shape": "text",
                "risk": "low",
                "timeout_seconds": 5,
                "reason": "Run the requested command.",
                "depends_on": [],
            }
        ],
        "dependencies": [],
        "expected_outputs": ["stdout"],
        "assumptions": [],
        "confidence": 0.95,
    }


def _tryout_capsule_batch_payload(
    *commands: str,
    cwd: str = ".",
    goal_complete_if_successful: bool = True,
    risk: str = "low",
    effect_intent: str = "read_only",
) -> dict[str, Any]:
    capsules: list[dict[str, Any]] = []
    for index, command in enumerate(commands, start=1):
        plan = _plan_payload(command=command, cwd=cwd)
        task = dict(plan["tasks"][0])
        action = dict(plan["actions"][0])
        task["task_id"] = f"task_{index}"
        action["task_id"] = task["task_id"]
        action["action_id"] = f"action_{index}"
        action["risk"] = risk
        action["effect_intent"] = effect_intent
        capsules.append(
            {
                "task": task,
                "action": action,
                "dependencies": [],
                "expected_output": "stdout",
                "reason": "Retired tryout capsule fixture.",
            }
        )
    return {
        "summary": "Draft compact retired tryout capsules.",
        "capsules": capsules,
        "goal_complete_if_successful": goal_complete_if_successful,
        "next_step_hint": "",
        "confidence": 0.91,
    }


def _tryout_result_review_payload(
    decision: str = "complete",
    *,
    issues: list[str] | None = None,
    repair_feedback: str = "",
    next_step_hint: str = "",
) -> dict[str, Any]:
    return {
        "decision": decision,
        "evidence_summary": "Reviewed retired tryout execution evidence.",
        "issues": list(issues or []),
        "repair_feedback": repair_feedback,
        "next_step_hint": next_step_hint,
        "reason": repair_feedback or "The evidence satisfies the request.",
        "confidence": 0.94,
    }


def _bound_shell_plan_payload(command: str = 'printf "%s\\n" "$OF_INPUT_COMMIT_HASH"') -> dict[str, Any]:
    plan = _plan_payload(command="git rev-parse HEAD")
    plan["tasks"][0]["goal"] = "Discover current commit hash"
    plan["tasks"][0]["object_type"] = "git.commit"
    plan["actions"][0]["reason"] = "Discover the commit hash to reuse downstream."
    plan["tasks"].append(
        {
            "task_id": "task_2",
            "goal": "Use the discovered commit hash",
            "semantic_verb": "execute",
            "object_type": "git.commit",
            "dependencies": ["task_1"],
            "reason": "The downstream shell command consumes the discovered commit hash.",
        }
    )
    plan["actions"].append(
        {
            "action_id": "action_2",
            "task_id": "task_2",
            "kind": "shell_command",
            "command": command,
            "cwd": ".",
            "inputs": {},
            "input_bindings": [
                {
                    "input_name": "commit_hash",
                    "source_action_id": "action_1",
                    "source_field": "stdout",
                    "required": True,
                    "fallback_value": None,
                }
            ],
            "declared_output_shape": "text",
            "risk": "high",
            "timeout_seconds": 5,
            "reason": "Use the upstream commit hash through a bound shell environment variable.",
            "depends_on": ["action_1"],
        }
    )
    plan["expected_outputs"] = ["commit hash used"]
    return plan


