def _generated_commit_consumer_plan_payload(cwd: str = ".") -> dict[str, Any]:
    plan = _llm_text_plan_payload()
    plan["tasks"].append(
        {
            "task_id": "task_3",
            "goal": "Commit the staged files with the generated message",
            "semantic_verb": "create",
            "object_type": "git.commit",
            "dependencies": ["task_2"],
            "reason": "The commit consumes the generated text as stdin.",
        }
    )
    plan["actions"].append(
        {
            "action_id": "action_3",
            "task_id": "task_3",
            "kind": "shell_command",
            "command": "git commit -F -",
            "cwd": cwd,
            "inputs": {},
            "input_bindings": [
                {
                    "input_name": "commit_message",
                    "source_action_id": "action_2",
                    "source_field": "stdout",
                    "required": True,
                    "fallback_value": None,
                }
            ],
            "stdin_mode": "input_binding",
            "stdin_input_name": "commit_message",
            "declared_output_shape": "text",
            "risk": "medium",
            "effect_intent": "mutates_state",
            "effect_confidence": 0.95,
            "effect_summary": "Commits the staged files with generated text.",
            "timeout_seconds": 30,
            "reason": "Feed the generated commit message through stdin.",
            "depends_on": ["action_2"],
        }
    )
    plan["dependencies"].append(
        {
            "producer_action_id": "action_2",
            "consumer_action_id": "action_3",
            "reason": "The commit action consumes the generated message.",
        }
    )
    plan["expected_outputs"] = ["generated message", "git commit result"]
    return plan


def _typein_macro_context(value: str = "abc") -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    private_macros = [
        {
            "macro_id": "macro_typein_1",
            "kind": "typein",
            "input_name": "typein_1",
            "value": value,
            "redacted": True,
            "value_length": len(value),
            "consumed": False,
        }
    ]
    public_summaries = [
        {
            "macro_id": "macro_typein_1",
            "kind": "typein",
            "input_name": "typein_1",
            "redacted": True,
            "value_length": len(value),
        }
    ]
    return private_macros, public_summaries


def _sudo_permission_failed_record(command: str = "dumpe2fs /dev/sdc2") -> OperatorExecutionRecord:
    return OperatorExecutionRecord(
        action_id="action_1",
        task_id="task_1",
        kind="shell_command",
        status="error",
        stdout="",
        stderr="dumpe2fs: Permission denied while trying to open /dev/sdc2\n",
        exit_code=13,
        error="dumpe2fs: Permission denied while trying to open /dev/sdc2\n",
        metadata={
            "shell_command": command,
            "permission_denied_sudo_candidate": True,
            "sudo_retry_reason": "The failed command output indicates sudo is needed.",
            "sudo_retry_original_command": command,
            "sudo_retry_proposed_command": f"sudo {command}",
        },
    )


