def test_cancelled_sudo_prompt_is_not_stdout_primary_success(tmp_path: Path) -> None:
    command = "sudo -k -v"
    plan = OperatorPlan.model_validate(_plan_payload(command=command, cwd=str(tmp_path)))
    gateway = CancelledTerminalPromptGateway()
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        gateway,
        config_overrides={
            "terminal_execution_enabled": True,
            "terminal_session_id": "term-test",
            "terminal_cwd": str(tmp_path),
            "operator_command_allowlist_hashes": [operator_command_hash(command)],
        },
    )

    result = pipeline.execute_approved(
        UserRequest(raw_prompt="run sudo"),
        plan,
        {
            "confirmation": True,
            "execute_in_terminal": True,
            "terminal_session_id": "term-test",
            "terminal_cwd": str(tmp_path),
        },
    )

    assert result.status == "error"
    assert result.execution_records[0].status == "error"
    assert result.execution_records[0].exit_code == 130
    assert result.execution_records[0].metadata.get("partial_stdout_available") is None
    assert result.execution_records[0].metadata.get("stdout_primary_success") is None
    assert "cancelled" in result.execution_records[0].error.lower()


def test_llm_sudo_judgement_pauses_for_sudo_clarification(tmp_path: Path) -> None:
    command = "diagnostic-tool --inspect target"
    plan = OperatorPlan.model_validate(_plan_payload(command=command, cwd=str(tmp_path)))
    gateway = FixedShellResultGateway(
        stdout="partial diagnostic output\n",
        stderr="diagnostic-tool: Permission denied while opening target\n",
        exit_code=13,
    )
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(_sudo_retry_judge_payload(reason="The output shows permission denial.")),
        gateway,
    )

    result = pipeline.execute_approved(
        UserRequest(raw_prompt="inspect the usb filesystem"),
        plan,
        {"confirmation": True},
    )

    assert result.status == "clarification_required"
    assert result.clarification_required is True
    assert result.clarification_request is not None
    assert result.clarification_request.question == (
        "This step previously failed and needs sudo to continue. "
        "Enter a sudo password or choose a saved credential to retry this exact command with sudo."
    )
    assert result.clarification_request.input_kind == "password"
    assert result.clarification_request.secret_input is True
    assert result.clarification_request.metadata["original_command"] == command
    assert result.clarification_request.metadata["proposed_sudo_command"] == f"sudo {command}"
    assert result.execution_records[0].status == "error"
    assert result.execution_records[0].metadata["permission_denied_sudo_candidate"] is True
    assert result.execution_records[0].metadata["sudo_retry_judge"]["confidence"] == 0.9
    assert result.execution_records[0].metadata.get("partial_stdout_available") is not True


