def test_secret_sudo_clarification_retries_with_terminal_typein_once(tmp_path: Path) -> None:
    command = "dumpe2fs /dev/sdc2"
    plan = OperatorPlan.model_validate(_plan_payload(command=command, cwd=str(tmp_path)))
    failed_record = _sudo_permission_failed_record(command)
    private_macros, public_summaries = _typein_macro_context("sudo-secret")
    gateway = TypeinPromptGateway()
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(_formatter_payload("inspected")),
        gateway,
        config_overrides={
            "terminal_session_id": "term-test",
            "terminal_cwd": str(tmp_path),
        },
    )

    result = pipeline.execute_approved(
        UserRequest(
            raw_prompt="inspect the usb filesystem",
            safety_context={USER_MACRO_PRIVATE_CONTEXT_KEY: private_macros},
            session_context={
                USER_MACRO_SUMMARY_CONTEXT_KEY: public_summaries,
                "operator_seed_records": [failed_record.model_dump(mode="json")],
                "clarifications": [
                    {
                        "question": (
                            "This step previously failed and needs sudo to continue. "
                            "Enter a sudo password or choose a saved credential to retry this exact command with sudo."
                        ),
                        "answer": "[redacted]",
                        "answer_is_secret": True,
                        "answer_redacted": True,
                        "missing_information": "Sudo password or saved credential to retry this command",
                    }
                ],
            },
        ),
        plan,
        {
            "confirmation": True,
            "operator_resume_after_clarification": True,
            "operator_seed_records": [failed_record.model_dump(mode="json")],
            "terminal_session_id": "term-test",
            "terminal_cwd": str(tmp_path),
            USER_MACRO_PRIVATE_CONTEXT_KEY: private_macros,
        },
    )

    assert result.status == "success"
    assert gateway.terminal_calls[0]["command"] == f"sudo {command}"
    assert len(gateway.terminal_calls) == 1
    assert [item["text"] for item in gateway.terminal_inputs] == ["sudo-secret\n"]
    assert "sudo-secret" not in str(result.execution_records)


