class BoundShellValueGateway(FakeOperatorGateway):
    def __init__(self, first_stdout: str = "abc123\n") -> None:
        super().__init__()
        self.first_stdout = first_stdout

    def execute_raw_command(
        self,
        *,
        command: str,
        cwd: str,
        execution_context: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        context = dict(execution_context or {})
        self.raw_calls.append({"command": command, "cwd": cwd, "execution_context": context})
        if len(self.raw_calls) == 1:
            return {"stdout": self.first_stdout, "stderr": "", "exit_code": 0, "gateway_node": "fake"}
