class DiagnosticThenCorrectedShellGateway(FakeOperatorGateway):
    def __init__(
        self,
        *,
        failed_command: str,
        successful_command: str,
        failed_stdout: str = "ERROR: Option --query-memory=free is not recognized. Please run 'nvidia-smi -h'.\n",
        failed_stderr: str = "",
        successful_stdout: str = "596\n",
    ) -> None:
        super().__init__()
        self.failed_command = failed_command
        self.successful_command = successful_command
        self.failed_stdout = failed_stdout
        self.failed_stderr = failed_stderr
        self.successful_stdout = successful_stdout

    def execute_raw_command(
        self,
        *,
        command: str,
        cwd: str,
        execution_context: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        self.raw_calls.append(
            {"command": command, "cwd": cwd, "execution_context": dict(execution_context or {})}
        )
        if command == self.failed_command:
            return {
                "stdout": self.failed_stdout,
                "stderr": self.failed_stderr,
                "exit_code": 255,
                "gateway_node": "fake",
            }
        if command == self.successful_command:
            return {
                "stdout": self.successful_stdout,
                "stderr": "",
                "exit_code": 0,
                "gateway_node": "fake",
            }
        raise AssertionError(f"Unexpected shell command: {command}")


