class DeferredPythonExecutionRepairGateway(FakeOperatorGateway):
    @staticmethod
    def _decoded_python_payload(command: str) -> str:
        marker = "printf %s "
        if marker not in command:
            return ""
        token = command.split(marker, 1)[1].split(" ", 1)[0]
        try:
            runner = base64.b64decode(token).decode("utf-8")
        except Exception:
            return ""
        code_marker = "code = base64.b64decode('"
        if code_marker not in runner:
            return runner
        encoded_code = runner.split(code_marker, 1)[1].split("'", 1)[0]
        try:
            code = base64.b64decode(encoded_code).decode("utf-8")
        except Exception:
            code = ""
        return f"{runner}\n{code}"

    def execute_raw_command(
        self,
        *,
        command: str,
        cwd: str,
        execution_context: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        self.raw_calls.append(
            {"command": command, "cwd": cwd, "execution_context": dict(execution_context or {})}
        )
        if not command.startswith("python3 -c"):
            return {
                "stdout": "postgres:15 633MB\nalpine:latest 13.1MB\nvllm/vllm-openai:latest 32.2GB\n",
                "stderr": "",
                "exit_code": 0,
                "gateway_node": "fake",
            }
        python_calls = sum(
            1 for call in self.raw_calls if str(call.get("command") or "").startswith("python3 -c")
        )
        payload = self._decoded_python_payload(command)
        if python_calls >= 2 or "Total Docker image size: 32.83 GB" in payload:
            return {
                "stdout": "Total Docker image size: 32.83 GB\n",
                "stderr": "",
                "exit_code": 0,
                "gateway_node": "fake",
            }
        return {
            "stdout": "Traceback...\nValueError: could not convert string to float: '633M'\n",
            "stderr": "",
            "exit_code": 1,
            "gateway_node": "fake",
        }


