def _pipeline(
    tmp_path: Path,
    llm: QueueLLM,
    gateway: FakeOperatorGateway | None = None,
    *,
    config_overrides: dict[str, Any] | None = None,
    memory_store: AgentMemoryStore | None = None,
    plan_cache_store: AgentPlanCacheStore | None = None,
    command_template_cache_store: AgentCommandTemplateCacheStore | None = None,
    computation_cache_store: AgentComputationCacheStore | None = None,
    reliability_store: AgentReliabilityStore | None = None,
) -> LLMOperatorPipeline:
    config_payload = {
        "workspace_root": str(tmp_path),
        "allow_shell_execution": True,
        "gateway_url": "http://gateway",
        "gateway_timeout_seconds": 30,
    }
    config_payload.update(dict(config_overrides or {}))
    return LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=gateway or FakeOperatorGateway(),  # type: ignore[arg-type]
        config=RuntimeConfig(**config_payload),
        result_store=InMemoryResultStore(),
        memory_store=memory_store,
        plan_cache_store=plan_cache_store,
        command_template_cache_store=command_template_cache_store,
        computation_cache_store=computation_cache_store,
        reliability_store=reliability_store,
    )


def test_machine_operator_pipeline_uses_compact_contracts(tmp_path: Path) -> None:
    request = UserRequest(raw_prompt="print hello", session_context={})
    llm = QueueLLM(
        _plan_payload(command="printf hello", cwd=str(tmp_path)),
    )
    pipeline = MachineOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
            config=RuntimeConfig(
                workspace_root=str(tmp_path),
                allow_shell_execution=True,
                llm_operator_verbose_enabled=False,
            ),
        result_store=InMemoryResultStore(),
    )

    plan, errors = pipeline.propose_and_validate(request)

    assert errors == []
    assert plan.actions[0].command == "printf hello"
    assert llm.schemas == ["OperatorPlan"]
    assert "Machine compact mode" in llm.prompts[0]


def test_operator_pipeline_type_follows_compact_profile_policy(tmp_path: Path) -> None:
    registry = build_default_registry()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
        ),
        InMemoryResultStore(),
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
    )
    runtime = AgentRuntime(QueueLLM(), registry, engine, OutputPipelineOrchestrator())

    assert isinstance(
        runtime._operator_pipeline(
            context={
                "reasoning_profile": "fast",
                "llm_operator_verbose_enabled": True,
            }
        ),
        MachineOperatorPipeline,
    )
    assert isinstance(
        runtime._operator_pipeline(
            context={
                "reasoning_profile": "balanced",
                "llm_operator_verbose_enabled": True,
            }
        ),
        MachineOperatorPipeline,
    )
    assert isinstance(
        runtime._operator_pipeline(
            context={
                "reasoning_profile": "deep",
                "llm_operator_verbose_enabled": True,
            }
        ),
        LLMOperatorPipeline,
    )
    assert isinstance(
        runtime._operator_pipeline(
            context={
                "reasoning_profile": "deep",
                "llm_operator_verbose_enabled": False,
            }
        ),
        MachineOperatorPipeline,
    )


