def test_report_markdown_wraps_raw_terminal_output_as_code_block() -> None:
    record = OperatorExecutionRecord(
        action_id="action_1",
        task_id="task_1",
        kind="shell_command",
        status="success",
        stdout=(
            "Enumerating objects: 3, done.\r"
            "Counting objects: 100% (3/3)\x1b[K\r"
            "Writing objects: 100% (3/3), done.\n"
            "To github.com:example/repo.git\n"
        ),
        stderr="",
        exit_code=0,
    )

    markdown = report_markdown_from_records([record])

    assert markdown.startswith("```text\n")
    assert "\x1b" not in markdown
    assert "\r" not in markdown
    assert "Counting objects: 100% (3/3)" in markdown
    assert "To github.com:example/repo.git" in markdown


