def test_lrdirect_streaming_suppresses_operator_conversation_followup_shortcut(
    tmp_path: Path,
) -> None:
    registry = build_default_registry()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
        ),
        InMemoryResultStore(),
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
    )
    llm = QueueLLM(
        _tool_classification_payload(["operator"]),
        {
            "tasks": [
                {
                    "id": "task_1",
                    "description": "Stage all changes",
                    "semantic_verb": "execute",
                    "object_type": "git.changes",
                    "intent_confidence": 0.95,
                    "dependencies": [],
                    "requires_confirmation": True,
                    "risk_level": "high",
                    "operation_intent": "mutate git index",
                    "side_effect_type": "operator_action",
                    "constraints": {},
                    "dependency_hints": [],
                },
                {
                    "id": "task_2",
                    "description": "Commit staged changes",
                    "semantic_verb": "create",
                    "object_type": "git.commit",
                    "intent_confidence": 0.95,
                    "dependencies": ["task_1"],
                    "requires_confirmation": True,
                    "risk_level": "high",
                    "operation_intent": "create git commit",
                    "side_effect_type": "operator_action",
                    "constraints": {},
                    "dependency_hints": ["task_1"],
                },
            ],
            "global_constraints": {},
            "unresolved_references": [],
            "assumptions": [],
        },
        _decomposition_critique_payload(),
        {
            "assignments": [
                {
                    "task_id": "task_1",
                    "semantic_verb": "execute",
                    "object_type": "git.changes",
                    "intent_confidence": 0.9,
                    "risk_level": "high",
                    "requires_confirmation": True,
                },
                {
                    "task_id": "task_2",
                    "semantic_verb": "create",
                    "object_type": "git.commit",
                    "intent_confidence": 0.9,
                    "risk_level": "high",
                    "requires_confirmation": True,
                },
            ]
        },
    )
    runtime = AgentRuntime(llm, registry, engine, OutputPipelineOrchestrator())
    calls = {"operator": 0, "streaming": 0}

    def fake_operator(*args: Any, **kwargs: Any) -> str:
        calls["operator"] += 1
        return "operator-followup"

    def fake_streaming(*args: Any, **kwargs: Any) -> str:
        calls["streaming"] += 1
        return "streaming-route"

    runtime._handle_operator_request = fake_operator  # type: ignore[method-assign]
    runtime._handle_streaming_operator_request = fake_streaming  # type: ignore[method-assign]

    result = runtime.handle_request(
        "stage all and commit",
        {
            "workspace_root": str(tmp_path),
            "agent_mode": "llm_operator",
            "workflow_execution_mode": "streaming",
            "lrdirect_enabled": True,
            "operator_conversation_context": {
                "conversation_id": "conv-test",
                "turns": [{"user_prompt": "prior request"}],
            },
        },
    )

    assert result == "streaming-route"
    assert calls == {"operator": 0, "streaming": 1}
    assert runtime.last_planning_trace.metadata[
        "operator_conversation_followup_suppressed_for_lrdirect_streaming"
    ] is True
    assert "OperatorFollowupDecision" not in llm.schemas


def test_lrnt_learns_streaming_total_task_and_lrt_hit_skips_decomposition(
    tmp_path: Path,
) -> None:
    registry = build_default_registry()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            lrnt_enabled=True,
        ),
        InMemoryResultStore(),
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
    )
    store = AgentLrnTotalTaskStore(tmp_path / "lrnt.db")
    first_llm = QueueLLM(
        _tool_classification_payload(["operator"]),
        {
            "tasks": [
                {
                    "id": "task_1",
                    "description": "List changed files",
                    "semantic_verb": "list",
                    "object_type": "git.changes",
                    "intent_confidence": 0.95,
                    "dependencies": [],
                    "requires_confirmation": False,
                    "risk_level": "low",
                    "operation_intent": "read changed files",
                    "side_effect_type": None,
                    "constraints": {},
                    "dependency_hints": [],
                },
                {
                    "id": "task_2",
                    "description": "Summarize the changes",
                    "semantic_verb": "summarize",
                    "object_type": "git.changes",
                    "intent_confidence": 0.95,
                    "dependencies": ["task_1"],
                    "requires_confirmation": False,
                    "risk_level": "low",
                    "operation_intent": "summarize changed files",
                    "side_effect_type": None,
                    "constraints": {},
                    "dependency_hints": ["task_1"],
                },
            ],
            "global_constraints": {"format": "bullets"},
            "unresolved_references": [],
            "assumptions": [],
        },
        _decomposition_critique_payload(),
        {
            "assignments": [
                {
                    "task_id": "task_1",
                    "semantic_verb": "list",
                    "object_type": "git.changes",
                    "intent_confidence": 0.95,
                    "risk_level": "low",
                    "requires_confirmation": False,
                },
                {
                    "task_id": "task_2",
                    "semantic_verb": "summarize",
                    "object_type": "git.changes",
                    "intent_confidence": 0.95,
                    "risk_level": "low",
                    "requires_confirmation": False,
                },
            ]
        },
    )
    runtime = AgentRuntime(
        first_llm,
        registry,
        engine,
        OutputPipelineOrchestrator(),
        lrn_total_task_store=store,
    )
    streaming_calls: list[list[TaskFrame]] = []

    def fake_streaming(*args: Any, **kwargs: Any) -> str:
        streaming_calls.append(list(kwargs["tasks"]))
        runtime.last_profile_summary = {"final_status": "success"}
        return "streaming-route"

    runtime._handle_streaming_operator_request = fake_streaming  # type: ignore[method-assign]

    first_result = runtime.handle_request(
        "list changed files and summarize them",
        {
            "workspace_root": str(tmp_path),
            "workflow_execution_mode": "streaming",
        },
    )

    assert first_result == "streaming-route"
    assert store.stats().active_entries == 1
    assert "PromptClassificationProposal" in first_llm.schemas
    assert "MachineDecompositionProposal" in first_llm.schemas or "TaskDecompositionProposal" in first_llm.schemas

    second_llm = QueueLLM(_tool_classification_payload(["operator"]))
    runtime.llm_client = second_llm

    second_result = runtime.handle_request(
        "list changed file and summarize them",
        {
            "workspace_root": str(tmp_path),
            "workflow_execution_mode": "streaming",
        },
    )

    assert second_result == "streaming-route"
    assert len(streaming_calls) == 2
    assert [task.id for task in streaming_calls[1]] == ["task_1", "task_2"]
    assert "PromptClassificationProposal" in second_llm.schemas
    assert "MachineDecompositionProposal" not in second_llm.schemas
    assert "TaskDecompositionProposal" not in second_llm.schemas
    assert "VerbAssignmentProposal" not in second_llm.schemas
    assert runtime.last_planning_trace.metadata["lrt_hit"]["task_count"] == 2
    assert store.stats().total_uses == 1


def test_lrt_reused_failure_quarantines_total_task_entry(tmp_path: Path) -> None:
    registry = build_default_registry()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            lrnt_enabled=True,
        ),
        InMemoryResultStore(),
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
    )
    store = AgentLrnTotalTaskStore(tmp_path / "lrnt.db")
    store.upsert_entry(
        LrnTotalTaskWrite(
            prompt="list changed files and summarize them",
            classification_context={
                "prompt_type": "simple_tool_task",
                "requires_tools": True,
                "likely_domains": ["operator"],
                "risk_level": "low",
            },
            model_name="fake-operator",
            model_family=normalize_model_family("fake-operator"),
            workflow_mode="streaming",
            registry_contract_hash=orchestrator_module.registry_contract_hash(
                registry.planning_view()
            ),
            tasks=[
                TaskFrame(
                    id="task_1",
                    description="List changed files",
                    semantic_verb="list",
                    object_type="git.changes",
                    intent_confidence=0.95,
                    constraints={"global_constraints": {}},
                    dependencies=[],
                    risk_level="low",
                ).model_dump(mode="json")
            ],
            global_constraints={},
            routing_metadata={"streaming_operator_mode": True},
        )
    )
    llm = QueueLLM(_tool_classification_payload(["operator"]))
    runtime = AgentRuntime(
        llm,
        registry,
        engine,
        OutputPipelineOrchestrator(),
        lrn_total_task_store=store,
    )

    def failing_streaming(*args: Any, **kwargs: Any) -> str:
        runtime.last_profile_summary = {"final_status": "error"}
        return "failed"

    runtime._handle_streaming_operator_request = failing_streaming  # type: ignore[method-assign]

    result = runtime.handle_request(
        "list changed files and summarize them",
        {
            "workspace_root": str(tmp_path),
            "workflow_execution_mode": "streaming",
        },
    )

    assert result == "failed"
    stats = store.stats()
    assert stats.active_entries == 0
    assert stats.quarantined_entries == 1
    assert runtime.last_planning_trace.metadata["lrt_quarantined"]["final_status"] == "error"


def test_streaming_prompt_tells_planner_to_bind_prior_outputs() -> None:
    request = UserRequest(
        raw_prompt="list docker images and tell me the total size",
        session_context={
            "operator_streaming_current_task": {
                "id": "task-3",
                "description": "Calculate the total size of all Docker images in GB",
                "semantic_verb": "calculate",
                "object_type": "docker.image",
            },
            "operator_streaming_prior_results": {
                "completed_tasks": [
                    {
                        "task_id": "task-2",
                        "description": "List all Docker images",
                        "status": "success",
                        "records": [
                            {
                                "action_id": "action-2",
                                "task_id": "task-2",
                                "kind": "shell_command",
                                "status": "success",
                                "stdout": "abc123\trepo\tlatest\t1.5GB\n",
                                "stderr": "",
                                "exit_code": 0,
                            }
                        ],
                    }
                ]
            },
        },
    )

    prompt = build_operator_plan_prompt(request)

    assert "do not copy prior stdout/output into literal action inputs" in prompt
    assert "Bind the prior action output with input_bindings" in prompt
    assert "Do not copy computed runtime values into literal inputs or command text" in prompt
    assert "deduplicate by a stable entity identifier" in prompt
    assert "For per-entity tasks" in prompt
    assert "one row per entity" in prompt
    assert "head -n 1" in prompt


