def test_streaming_per_entity_task_rejects_global_scalar_selector(
    tmp_path: Path,
) -> None:
    payload = _plan_payload(
        command='git log --oneline --date=short --format="%ad" --all | head -n 1',
        cwd=str(tmp_path),
    )
    payload["tasks"][0].update(
        {
            "task_id": "task_2",
            "goal": "Extract the date of the most recent commit for each branch",
            "semantic_verb": "extract",
            "object_type": "git.branch",
        }
    )
    payload["actions"][0].update(
        {
            "task_id": "task_2",
            "reason": "Get the latest commit date.",
            "effect_summary": "Retrieves one latest commit date across all branches.",
        }
    )
    plan = OperatorPlan.model_validate(payload)
    pipeline = _pipeline(tmp_path, QueueLLM())
    request = UserRequest(
        raw_prompt="list git branches and extract the date of most recent commits for each branch",
        session_context=_branch_list_prior_context(),
    )

