def test_step_validation_repair_guidance_becomes_authoritative_policy_note() -> None:
    step_context: dict[str, Any] = {}
    step_request = UserRequest(raw_prompt="retry current step")
    guidance = "Loop through all prior branches and emit one row per branch."

    AgentRuntime._attach_step_validation_feedback_context(
        step_context=step_context,
        step_request=step_request,
        feedback={
            "decision": "repair",
            "reason": "The first attempt only inspected the current branch.",
            "repair_guidance": guidance,
        },
    )

    assert step_context["operator_bypass_lr_for_step_validation_retry"] is True
    assert step_request.session_context["operator_bypass_lr_for_step_validation_retry"] is True
    prompt = build_operator_plan_prompt(step_request)
    assert guidance in prompt
    assert "Runtime-enforced operator policy notes" in prompt


def test_streaming_prompt_preserves_original_request_step_focus_future_and_contract() -> None:
    original = "inspect every project, report status, then restart failing ones"
    execution_shape = {
        "shape": "staged_workflow",
        "preferred_action_count": None,
        "hard_max_action_count": None,
        "decomposition_policy": "force",
        "report_contract": {
            "scope": "all_entities",
            "entity_label": "project",
            "required_fields": ["status"],
            "field_types": {"status": "text"},
        },
        "reason": "The request has a read step followed by a mutating step.",
    }
    request = UserRequest(
        raw_prompt="Streaming step 2 of 3: summarize statuses",
        session_context={
            "execution_shape": execution_shape,
            "operator_intent_block": {
                "mode": "decomposition_streaming_step",
                "global_constraints": {"streaming_original_prompt": original},
                "execution_shape": execution_shape,
                "tasks": [],
            },
            "operator_streaming_current_task": {
                "id": "task-2",
                "description": "Summarize status for every project",
                "semantic_verb": "summarize",
                "object_type": "project",
            },
            "operator_streaming_tasks": [
                {
                    "task_id": "task-1",
                    "description": "Inspect projects",
                    "semantic_verb": "list",
                    "object_type": "project",
                },
                {
                    "task_id": "task-2",
                    "description": "Summarize status for every project",
                    "semantic_verb": "summarize",
                    "object_type": "project",
                },
                {
                    "task_id": "task-3",
                    "description": "Restart failing projects",
                    "semantic_verb": "execute",
                    "object_type": "project",
                },
            ],
            "operator_streaming_current_index": 1,
            "operator_streaming_prior_results": {
                "completed_tasks": [
                    {
                        "task_id": "task-1",
                        "description": "Inspect projects",
                        "status": "success",
                        "records": [
                            {
                                "action_id": "action-1",
                                "task_id": "task-1",
                                "kind": "shell_command",
                                "status": "success",
                                "stdout": "api ok\nworker failing\n",
                                "stderr": "",
                                "exit_code": 0,
                            }
                        ],
                    }
                ]
            },
        },
    )

    prompt = build_operator_plan_prompt(request)

    assert f"Original user request: {original}" in prompt
    assert "Summarize status for every project" in prompt
    assert "Restart failing projects" in prompt
    assert "api ok" in prompt
    assert "Original request success contract" in prompt
    assert "preserve typed obligations from the original request" in prompt


