def test_operator_rejects_shell_arithmetic_over_human_readable_units(
    tmp_path: Path,
) -> None:
    payload = _plan_payload(
        command=(
            "docker images --format \"{{.ID}}\\t{{.Size}}\" | "
            "awk '{size[$1] += $2} END {for (id in size) print size[id]}' | "
            "awk '{sum += $1} END {print sum}'"
        ),
        cwd=str(tmp_path),
    )
    payload["summary"] = "Calculate total image size."
    payload["tasks"][0]["goal"] = "Calculate the total size of listed images"
    payload["tasks"][0]["semantic_verb"] = "calculate"
    payload["tasks"][0]["object_type"] = "image.size"
    payload["actions"][0]["reason"] = "Calculate total image size from human-readable size fields."
    payload["actions"][0]["effect_summary"] = "Aggregates image sizes."
    plan = OperatorPlan.model_validate(payload)
    pipeline = _pipeline(tmp_path, QueueLLM())

    errors = pipeline._validate_plan(
        UserRequest(raw_prompt="list images and calculate their total size"),
        plan,
    )

    assert any(error["error"] == "human_unit_shell_arithmetic" for error in errors)


