def test_operator_pipeline_adapts_strong_plan_cache_hit(tmp_path: Path) -> None:
    cache = AgentPlanCacheStore(tmp_path / "plan-cache.db")
    cache.upsert_entry(
        PlanCacheWrite(
            prompt="run cached command",
            mode="Conversational",
            model_name="fake-operator",
            tool_type="shell",
            tags=["cached", "command"],
            plan=_plan_payload("printf old"),
            status="success",
        )
    )
    llm = QueueLLM(
        {
            "decision": "use_adapted_plan",
            "adapted_plan": _plan_payload("printf cached"),
            "clarification_request": None,
            "reason": "The cached shell structure still fits.",
            "confidence": 0.92,
        }
    )
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
            config=RuntimeConfig(
                workspace_root=str(tmp_path),
                allow_shell_execution=True,
                gateway_url="http://gateway",
                gateway_timeout_seconds=30,
                workflow_execution_mode="full_plan",
                llm_operator_self_brief_mode="always",
            ),
        result_store=InMemoryResultStore(),
        plan_cache_store=cache,
    )

    plan, errors = pipeline.propose_and_validate(
        UserRequest(raw_prompt="run cached command", session_context={"operator_mode_label": "Conversational"})
    )

    assert errors == []
    assert plan.actions[0].command == "printf cached"
    assert llm.schemas == ["OperatorPlanCacheDecision"]
    cache_candidates = cache.retrieve(
        PlanCacheLookupContext(
            prompt="run cached command",
            mode="Conversational",
            model_name="fake-operator",
            tool_type="shell",
            tags=["cached", "command"],
        )
    )
    assert cache.get_entry(cache_candidates[0].entry.cache_id).use_count == 1  # type: ignore[union-attr]


def test_operator_plan_cache_hit_is_checked_against_memory_directives(tmp_path: Path) -> None:
    cache = AgentPlanCacheStore(tmp_path / "plan-cache.db")
    cache.upsert_entry(
        PlanCacheWrite(
            prompt='git commit current changes with message "cached"',
            mode="Conversational",
            model_name="fake-operator",
            tool_type="shell",
            tags=["git", "commit"],
            plan=_plan_payload("git add . && git commit -m cached"),
            status="success",
        )
    )
    repaired_plan = _plan_payload(
        "if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then "
        "git add . && git commit -m cached; "
        "else echo 'Not a git repository'; fi"
    )
    llm = QueueLLM(
        {
            "decision": "use_adapted_plan",
            "adapted_plan": _plan_payload("git add . && git commit -m cached"),
            "clarification_request": None,
            "reason": "The cached structure fits.",
            "confidence": 0.92,
        },
        _memory_compliance_payload(
            "repair_required",
            repaired_plan,
            memory_ids=["mem_git_guard"],
            confidence=0.93,
        ),
    )
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            gateway_timeout_seconds=30,
            workflow_execution_mode="full_plan",
            llm_operator_self_brief_mode="always",
        ),
        result_store=InMemoryResultStore(),
        plan_cache_store=cache,
    )
    request = UserRequest(
        raw_prompt='git commit current changes with message "cached"',
        session_context={
            "operator_mode_label": "Conversational",
            "agent_memory_directives": [
                {
                    "memory_id": "mem_git_guard",
                    "instruction": "Before any git add or git commit, prove this is a git repository.",
                    "memory_kind": "task_memory",
                    "applies_to": ["cache", "plan_review", "operator_plan"],
                    "strength": "required_unless_conflict",
                    "summary": "Check repo before commit.",
                    "safe_examples": [],
                    "blocked_examples": [],
                    "match_reasons": ["test"],
                    "score": 300,
                }
            ],
        },
    )

    plan, errors = pipeline.propose_and_validate(request)

    assert errors == []
    assert "git rev-parse --is-inside-work-tree" in str(plan.actions[0].command)
    assert llm.schemas == ["OperatorPlanCacheDecision", "MemoryComplianceReview"]


