def test_operator_pipeline_learns_may_prompt_command_template(
    tmp_path: Path,
) -> None:
    cache = AgentCommandTemplateCacheStore(tmp_path / "command-template-cache.db")
    llm = QueueLLM(
        {
            "decision": "store_template",
            "command_template": "printf ready",
            "variables": [],
            "reason": "The prompted command shape is reusable.",
            "confidence": 0.92,
        }
    )
    pipeline = _pipeline(
        tmp_path,
        llm,
        command_template_cache_store=cache,
    )
    payload = _plan_payload("printf ready", cwd=str(tmp_path))
    payload["actions"][0]["interaction_mode"] = "may_prompt"
    payload["actions"][0]["risk"] = "high"
    plan = OperatorPlan.model_validate(payload)
    action = plan.actions[0]
    private_macros, public_summaries = _typein_macro_context("abc")
    request = UserRequest(
        raw_prompt='run prompted command typein "[redacted]"',
        session_context={
            "operator_mode_label": "Conversational",
            USER_MACRO_SUMMARY_CONTEXT_KEY: public_summaries,
        },
        safety_context={USER_MACRO_PRIVATE_CONTEXT_KEY: private_macros},
    )
    record = OperatorExecutionRecord(
        action_id=action.action_id,
        task_id=action.task_id,
        kind="shell_command",
        status="success",
        stdout="ready",
        stderr="",
        exit_code=0,
        metadata={"cwd": str(tmp_path)},
    )

    pipeline._write_command_template_cache_result(
        request,
        plan,
        action,
        record,
        {"confirmation": True},
        None,
    )

    assert llm.schemas == ["OperatorCommandTemplateDraft"]
    candidates = cache.retrieve(
        CommandTemplateLookupContext(
            prompt="run prompted command",
            step_description="run prompted command",
            mode="Conversational",
            model_name="fake-operator",
            task_type="shell",
            tool_type="shell",
            intent_type="execute",
            tags=["prompted", "printf"],
            similarity_threshold=0.1,
        )
    )
    assert len(candidates) == 1
    entry = candidates[0].entry
    assert entry.command_template == "printf ready"
    assert entry.interaction_mode == "may_prompt"
    assert "typein" not in entry.prompt_excerpt.lower()
    assert "typein" not in entry.tags


