def test_operator_pipeline_reuses_command_template_before_full_plan_generation(
    tmp_path: Path,
) -> None:
    cache = AgentCommandTemplateCacheStore(tmp_path / "command-template-cache.db")
    entry = cache.upsert_entry(
        CommandTemplateWrite(
            prompt="say hello",
            step_description="Print a greeting",
            mode="Conversational",
            model_name="fake-operator",
            cwd=str(tmp_path),
            task_type="shell",
            tool_type="shell",
            intent_type="execute",
            tags=["hello", "greeting", "printf"],
            command_template='printf "$OF_INPUT_MESSAGE"',
            variables=[
                {
                    "name": "message",
                    "description": "Message to print.",
                    "observed_value": "hello",
                }
            ],
            observed_command="printf hello",
            risk="low",
            effect_intent="read_only",
            effect_summary="Prints a greeting.",
        )
    )
    llm = QueueLLM(
        {
            "decision": "use_template",
            "selected_template_id": entry.template_id,
            "variables": {"message": "hello"},
            "reason": "The learned greeting command matches the current step.",
            "confidence": 0.96,
        }
    )
    gateway = FakeOperatorGateway()
    pipeline = _pipeline(
        tmp_path,
        llm,
        gateway,
        config_overrides={
            "agent_command_template_cache_similarity_threshold": 0.1,
            "llm_operator_final_response_mode": "simple",
        },
        command_template_cache_store=cache,
    )
    request = UserRequest(
        raw_prompt="say hello again",
        session_context={
            "operator_mode_label": "Conversational",
            "operator_streaming_current_task": {
                "id": "task_2",
                "description": "Print a greeting",
                "semantic_verb": "execute",
                "object_type": "shell",
            },
            "operator_streaming_tasks": [
                {
                    "task_id": "task_2",
                    "description": "Print a greeting",
                    "semantic_verb": "execute",
                    "object_type": "shell",
                },
                {
                    "task_id": "task_3",
                    "description": "Archive the greeting",
                    "semantic_verb": "write",
                    "object_type": "file",
                },
            ],
        },
    )

    plan, errors = pipeline.propose_and_validate(request)

    assert errors == []
    assert llm.schemas == ["OperatorCommandTemplateDecision"]
    assert len(plan.tasks) == 1
    assert plan.tasks[0].task_id == "task_2"
    assert plan.actions[0].command == 'printf "$OF_INPUT_MESSAGE"'
    assert plan.actions[0].inputs == {"message": "hello"}
    assert (
        request.session_context["operator_command_template_cache_applied"]["template_id"]
        == entry.template_id
    )
    assert cache.get_entry(entry.template_id).use_count == 1  # type: ignore[union-attr]

    result = pipeline.execute_approved(request, plan, {"confirmation": True})

    assert result.status == "success"
    assert gateway.raw_calls[0]["command"] == 'printf "$OF_INPUT_MESSAGE"'
    assert gateway.raw_calls[0]["execution_context"]["shell_env"] == {"OF_INPUT_MESSAGE": "hello"}
    assert llm.schemas == ["OperatorCommandTemplateDecision"]


def test_operator_pipeline_does_not_relearn_after_command_template_hit(
    tmp_path: Path,
) -> None:
    cache = AgentCommandTemplateCacheStore(tmp_path / "command-template-cache.db")
    entry = cache.upsert_entry(
        CommandTemplateWrite(
            prompt="Retrieve staged change stats",
            step_description="Retrieve staged change stats",
            mode="Conversational",
            model_name="fake-operator",
            cwd=str(tmp_path),
            task_type="unknown",
            tool_type="unknown",
            intent_type="read",
            tags=["git", "diff", "cached", "stat"],
            command_template="git diff --cached --stat",
            observed_command="git diff --cached --stat",
            risk="low",
            effect_intent="read_only",
            effect_summary="Read staged change stats.",
        )
    )
    llm = QueueLLM(
        {
            "decision": "use_template",
            "selected_template_id": entry.template_id,
            "variables": {},
            "reason": "The learned git diff command matches this step.",
            "confidence": 0.95,
        }
    )
    pipeline = _pipeline(
        tmp_path,
        llm,
        config_overrides={
            "agent_command_template_cache_similarity_threshold": 0.1,
            "lrdirect_enabled": False,
        },
        command_template_cache_store=cache,
    )
    request = UserRequest(
        raw_prompt=(
            "Streaming step 2 of 4: Retrieve the status of staged files using "
            "git diff --cached --stat."
        ),
        session_context={
            "operator_mode_label": "Conversational",
            "operator_streaming_current_task": {
                "task_id": "task_2",
                "description": "Retrieve the status of staged files using git diff --cached --stat.",
                "semantic_verb": "read",
                "object_type": "unknown",
            },
        },
    )

    plan, errors = pipeline.propose_and_validate(request)

    assert errors == []
    assert cache.get_entry(entry.template_id).use_count == 1  # type: ignore[union-attr]
    request.session_context.pop("operator_command_template_cache_applied", None)

    result = pipeline.execute_approved(request, plan, {"confirmation": True})

    assert result.status == "success"
    assert cache.stats().total_entries == 1
    assert cache.get_entry(entry.template_id).success_count == 1  # type: ignore[union-attr]
    assert llm.schemas == ["OperatorCommandTemplateDecision"]


def test_lrdirect_step_metadata_is_stable_across_prompt_context_drift(
    tmp_path: Path,
) -> None:
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        config_overrides={"lrdirect_enabled": True},
    )
    base_task = {
        "task_id": "task_1",
        "description": "Stage all files using git add.",
        "semantic_verb": "execute",
        "object_type": "unknown",
    }
    first = UserRequest(
        raw_prompt=(
            "Stage all files, generate a detailed Conventional Commit message. "
            "Use git diff --cached --stat to see what changed."
        ),
        session_context={
            "lrdirect_enabled": True,
            "operator_streaming_current_index": 0,
            "operator_streaming_current_task": base_task,
            "operator_streaming_tasks": [
                base_task,
                {"description": "Commit with the generated message."},
            ],
            "operator_streaming_step_prompt": (
                "Streaming step 1 of 2: Stage all files using git add.\n"
                "Later steps reserved for future calls: Commit with message."
            ),
        },
    )
    second = UserRequest(
        raw_prompt=(
            "Stage all files, generate a detailed Conventional Commit message. "
            "Use git diff --cached --stat to see the changes and use that information."
        ),
        session_context={
            "lrdirect_enabled": True,
            "operator_streaming_current_index": 0,
            "operator_streaming_current_task": base_task,
            "operator_streaming_tasks": [
                base_task,
                {"description": "Generate message."},
                {"description": "Commit staged files."},
            ],
        },
    )

    first_key, first_excerpt = pipeline._lrdirect_step_metadata(first)
    second_key, second_excerpt = pipeline._lrdirect_step_metadata(second)

    assert first_key == second_key
    assert first_excerpt == second_excerpt
    assert first_excerpt.startswith("LRD canonical step:")
    assert "later steps" not in first_excerpt.lower()


def test_operator_pipeline_lrdirect_learns_and_replays_stage_command_canonically(
    tmp_path: Path,
) -> None:
    cache = AgentCommandTemplateCacheStore(tmp_path / "command-template-cache.db")
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        config_overrides={"lrdirect_enabled": True},
        command_template_cache_store=cache,
    )
    plan = OperatorPlan.model_validate(
        _plan_payload("git add --all", cwd=str(tmp_path))
    )
    plan.tasks[0].goal = "Stage all files using git add."
    plan.tasks[0].semantic_verb = "execute"
    plan.tasks[0].object_type = "unknown"
    plan.actions[0].risk = "medium"
    plan.actions[0].effect_intent = "mutates_state"
    plan.actions[0].effect_summary = "Stages all files."
    plan.actions[0].reason = "Stage all files using git add."
    record = OperatorExecutionRecord(
        action_id=plan.actions[0].action_id,
        task_id=plan.actions[0].task_id,
        kind="shell_command",
        status="success",
        stdout="",
        stderr="",
        exit_code=0,
        metadata={"cwd": str(tmp_path)},
    )
    learn_request = UserRequest(
        raw_prompt="Stage all files and then commit with a generated message.",
        session_context={
            "operator_mode_label": "Conversational",
            "lrdirect_enabled": True,
            "operator_streaming_current_index": 0,
            "operator_streaming_current_task": {
                "task_id": "task_1",
                "description": "Stage all files using git add.",
                "semantic_verb": "execute",
                "object_type": "unknown",
            },
        },
    )

    pipeline._write_command_template_cache_result(
        learn_request,
        plan,
        plan.actions[0],
        record,
        {"confirmation": True},
        None,
    )

    canonical_key, _ = pipeline._lrdirect_step_metadata(learn_request)
    assert len(cache.retrieve_exact_step(canonical_key)) == 1

    replay_request = UserRequest(
        raw_prompt=(
            "Stage all files, generate a detailed Conventional Commit message. "
            "Use git diff --cached --stat and commit."
        ),
        session_context={
            "operator_mode_label": "Conversational",
            "lrdirect_enabled": True,
            "operator_streaming_current_index": 0,
            "operator_streaming_current_task": {
                "task_id": "task_1",
                "description": "  stage ALL files using `git add` ",
                "semantic_verb": "execute",
                "object_type": "unknown",
            },
        },
    )

    replay_plan, errors = pipeline.propose_and_validate(replay_request)

    assert errors == []
    assert replay_plan.actions[0].command == "git add --all"
    assert (
        replay_request.session_context["operator_lrdirect_applied"]["bypassed_llm"]
        is True
    )


