def test_operator_pipeline_lrdirect_mutating_exact_command_keeps_approval_gate(
    tmp_path: Path,
) -> None:
    prompt = "Streaming step 1 of 3: Stage all files in the repository"
    cache = AgentCommandTemplateCacheStore(tmp_path / "command-template-cache.db")
    entry = cache.upsert_entry(
        CommandTemplateWrite(
            prompt=prompt,
            step_description="Stage all files in the repository",
            mode="Conversational",
            model_name="fake-operator",
            cwd=str(tmp_path),
            task_type="git.repository",
            tool_type="git",
            intent_type="execute",
            tags=["git", "stage"],
            exact_step_key=lrdirect_canonical_step_key(
                step_description="Stage all files in the repository",
                semantic_verb="execute",
                object_type="git.repository",
                step_locator="id=task_stage",
            ),
            exact_step_prompt_excerpt="LRD canonical step: stage all files in the repository",
            command_template="git add --all",
            observed_command="git add --all",
            direct_action={
                "kind": "shell_command",
                "command": "git add --all",
                "execution_mode": "captured",
                "interaction_mode": "non_interactive",
                "cwd": str(tmp_path),
                "inputs": {},
                "input_bindings": [],
                "stdin_mode": "none",
                "declared_output_shape": "text",
                "risk": "medium",
                "effect_intent": "mutates_state",
                "effect_confidence": 0.95,
                "effect_summary": "Stages all files.",
                "reason": "Stage all files.",
                "lrdirect_schema_version": 2,
            },
            risk="medium",
            effect_intent="mutates_state",
            effect_summary="Stages all files.",
            requires_confirmation=True,
            approval_observed=True,
            status="success",
        )
    )
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        config_overrides={
            "lrdirect_enabled": True,
            "llm_operator_final_response_mode": "simple",
        },
        command_template_cache_store=cache,
    )
    request = UserRequest(
        raw_prompt=prompt,
        session_context={
            "operator_mode_label": "Conversational",
            "lrdirect_enabled": True,
            "operator_streaming_current_task": {
                "task_id": "task_stage",
                "description": "Stage all files in the repository",
                "semantic_verb": "execute",
                "object_type": "git.repository",
            },
        },
    )

    plan, errors = pipeline.propose_and_validate(request)
    pending = pipeline.require_confirmation(request, plan)

    assert errors == []
    assert plan.actions[0].command == "git add --all"
    assert pipeline.plan_requires_confirmation(plan) is True
    assert "operator_lrdirect_bypass_confirmation" not in request.session_context
    assert request.session_context["operator_lrdirect_applied"]["cache_id"] == entry.template_id
    assert request.session_context["operator_lrdirect_applied"]["bypassed_llm"] is True
    assert request.session_context["operator_lrdirect_applied"]["bypassed_approval"] is False
    assert pending.status == "confirmation_required"


def test_streaming_lrdirect_mutating_exact_command_returns_confirmation_card(
    tmp_path: Path,
) -> None:
    prompt = "stage all files"
    task = TaskFrame.model_validate(
        {
            "id": "task-1",
            "description": "Stage all files in the repository",
            "semantic_verb": "execute",
            "object_type": "operator",
            "intent_confidence": 0.9,
            "constraints": {},
            "dependencies": [],
            "requires_confirmation": False,
            "risk_level": "low",
        }
    )
    registry = build_default_registry()
    gateway = FakeOperatorGateway()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
        ),
        InMemoryResultStore(),
        gateway_client=gateway,  # type: ignore[arg-type]
    )
    cache = AgentCommandTemplateCacheStore(tmp_path / "command-template-cache.db")
    runtime = AgentRuntime(
        QueueLLM(
            {**_tool_classification_payload(["operator"]), "risk_level": "high"},
            {
                "tasks": [
                    {
                        "id": "task-1",
                        "description": "Stage all files in the repository",
                        "semantic_verb": "execute",
                        "object_type": "operator",
                        "constraints": {},
                        "dependencies": [],
                        "requires_confirmation": False,
                        "risk_level": "low",
                        "operation_intent": "stage files for commit",
                        "side_effect_type": None,
                        "confidence": 0.9,
                    }
                ],
                "global_constraints": {},
                "unresolved_references": [],
                "confidence": 0.95,
            },
        ),
        registry,
        engine,
        OutputPipelineOrchestrator(),
        command_template_cache_store=cache,
    )
    state = runtime._new_streaming_state(
        original_prompt=prompt,
        tasks=[task],
        global_constraints={},
        classification_context={
            "likely_domains": ["operator"],
            "prompt_type": "simple_tool_task",
            "requires_tools": True,
            "risk_level": "high",
        },
        agent_mode="standard_operator",
    )
    step_prompt = runtime._streaming_step_prompt(state, state["tasks"][0])
    cache.upsert_entry(
        CommandTemplateWrite(
            prompt=step_prompt,
            step_description="Stage all files in the repository",
            mode="Conversational",
            model_name="fake-operator",
            cwd=str(tmp_path),
            task_type="unknown",
            tool_type="git",
            intent_type="execute",
            tags=["git", "stage"],
            exact_step_key=exact_step_key(step_prompt),
            exact_step_prompt_excerpt=step_prompt,
            command_template="git add --all",
            observed_command="git add --all",
            direct_action={
                "kind": "shell_command",
                "command": "git add --all",
                "execution_mode": "captured",
                "interaction_mode": "non_interactive",
                "cwd": str(tmp_path),
                "inputs": {},
                "input_bindings": [],
                "stdin_mode": "none",
                "declared_output_shape": "text",
                "risk": "medium",
                "effect_intent": "mutates_state",
                "effect_confidence": 0.95,
                "effect_summary": "Stages all files.",
                "reason": "Stage all files.",
                "lrdirect_schema_version": 2,
            },
            risk="medium",
            effect_intent="mutates_state",
            effect_summary="Stages all files.",
            requires_confirmation=True,
            approval_observed=True,
            status="success",
        )
    )

    result = runtime.handle_request(
        prompt,
        {
            "workspace_root": str(tmp_path),
            "operator_execution_mode": "streaming",
            "lrdirect_enabled": True,
        },
    )

    assert "Confirmation Required" in result
    assert "git add --all" in result
    assert gateway.raw_calls == []
    assert runtime.last_failure_summary is not None
    assert runtime.last_failure_summary["category"] == "confirmation_required"
    confirmation_action = runtime.last_planning_trace.metadata["operator_confirmation_actions"][0]
    assert confirmation_action["arguments"]["command"] == "git add --all"


