def test_operator_pipeline_lrdirect_suppresses_top_level_plan_cache_for_streaming(
    tmp_path: Path,
) -> None:
    plan_cache = AgentPlanCacheStore(tmp_path / "plan-cache.db")
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        config_overrides={
            "lrdirect_enabled": True,
            "workflow_execution_mode": "auto",
        },
        plan_cache_store=plan_cache,
    )

    top_level_request = UserRequest(
        raw_prompt="list all docker images and calculate total size",
        session_context={
            "lrdirect_enabled": True,
            "workflow_execution_mode": "auto",
        },
    )
    streaming_step_request = UserRequest(
        raw_prompt="List all Docker images",
        session_context={
            "lrdirect_enabled": True,
            "workflow_execution_mode": "auto",
            "operator_streaming_current_task": {
                "task_id": "task_1",
                "description": "List all Docker images",
            },
        },
    )
    regular_request = UserRequest(
        raw_prompt="list all docker images and calculate total size",
        session_context={
            "lrdirect_enabled": False,
            "workflow_execution_mode": "auto",
        },
    )

    assert pipeline._plan_cache_enabled(top_level_request) is False
    assert pipeline._plan_cache_enabled(streaming_step_request) is False
    assert pipeline._plan_cache_enabled(regular_request) is True


def test_operator_pipeline_writes_streaming_step_action_tree_cache(
    tmp_path: Path,
) -> None:
    prompt = "Stage all changes in the working directory for commit"
    cache = AgentPlanCacheStore(tmp_path / "plan-cache.db")
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        plan_cache_store=cache,
    )
    plan = OperatorPlan.model_validate(
        {
            "summary": "Stage all changes after proving this is a Git work tree.",
            "tasks": [
                {
                    "task_id": "old_task_stage",
                    "goal": "Stage all changes in the working directory for commit",
                    "semantic_verb": "update",
                    "object_type": "git.repository",
                    "dependencies": [],
                    "reason": "",
                }
            ],
            "actions": [
                {
                    "action_id": "old_action_probe",
                    "task_id": "old_task_stage",
                    "kind": "shell_command",
                    "command": "git rev-parse --is-inside-work-tree",
                    "cwd": str(tmp_path),
                    "declared_output_shape": "text",
                    "risk": "low",
                    "effect_intent": "read_only",
                    "reason": "Verify this is a Git work tree.",
                    "depends_on": [],
                },
                {
                    "action_id": "old_action_stage",
                    "task_id": "old_task_stage",
                    "kind": "shell_command",
                    "command": "git add --all",
                    "cwd": str(tmp_path),
                    "declared_output_shape": "text",
                    "risk": "medium",
                    "effect_intent": "mutates_state",
                    "reason": "Stage all changes.",
                    "depends_on": ["old_action_probe"],
                },
            ],
            "dependencies": [
                {
                    "producer_action_id": "old_action_probe",
                    "consumer_action_id": "old_action_stage",
                    "reason": "Only stage after the Git work tree check succeeds.",
                }
            ],
            "expected_outputs": ["Changes staged for commit."],
            "assumptions": [],
            "confidence": 0.95,
        }
    )
    result = OperatorPipelineResult(
        status="success",
        final_response="staged",
        plan=plan,
        execution_records=[
            OperatorExecutionRecord(
                action_id="old_action_probe",
                task_id="old_task_stage",
                kind="shell_command",
                status="success",
                stdout="true\n",
                stderr="",
                exit_code=0,
            ),
            OperatorExecutionRecord(
                action_id="old_action_stage",
                task_id="old_task_stage",
                kind="shell_command",
                status="success",
                stdout="",
                stderr="",
                exit_code=0,
            ),
        ],
        metadata={
            "operator_step_validation_checked": True,
            "operator_step_validation_decision": "accept",
        },
    )
    request = UserRequest(
        raw_prompt=prompt,
        session_context={
            "operator_mode_label": "Conversational",
            "operator_streaming_current_task": {
                "task_id": "task_stage_current",
                "description": prompt,
                "semantic_verb": "update",
                "object_type": "git.repository",
                "operation_intent": "Stage all files in the working directory for commit",
                "side_effect_type": "operator_action",
                "risk_level": "low",
            },
        },
    )

    pipeline._write_streaming_step_action_tree_cache_result(request, plan, result, None)

    exact_key, _ = pipeline._lrdirect_step_metadata(request)
    candidates = cache.retrieve_exact_step_tree(
        exact_key,
        intent_signature=pipeline._streaming_step_intent_signature(
            pipeline._streaming_step_intent_snapshot(request)
        ),
    )
    assert len(candidates) == 1
    direct_plan = candidates[0].entry.direct_plan
    serialized = str(direct_plan)
    assert "old_action_probe" not in serialized
    assert "old_action_stage" not in serialized
    assert "old_task_stage" not in serialized
    assert "stdout" not in serialized
    assert "exit_code" not in serialized
    assert candidates[0].entry.intent_snapshot["step_description"] == prompt
    assert [action["command"] for action in direct_plan["actions"]] == [
        "git rev-parse --is-inside-work-tree",
        "git add --all",
    ]


