def test_operator_pipeline_action_tree_rehydrates_current_commit_payload(
    tmp_path: Path,
) -> None:
    prompt = "Commit the staged changes with a message"
    cache = AgentPlanCacheStore(tmp_path / "plan-cache.db")
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        plan_cache_store=cache,
    )
    plan = OperatorPlan.model_validate(
        _plan_payload('git commit -m "$OF_INPUT_COMMIT_MESSAGE"', cwd=str(tmp_path))
    )
    plan.tasks[0].semantic_verb = "create"
    plan.tasks[0].object_type = "git.commit"
    plan.actions[0].inputs = {"commit_message": "Old cached message"}
    plan.actions[0].risk = "medium"
    plan.actions[0].effect_intent = "mutates_state"
    request = UserRequest(
        raw_prompt=prompt,
        session_context={
            "operator_mode_label": "Conversational",
            "operator_streaming_current_task": {
                "task_id": "task_commit",
                "description": prompt,
                "semantic_verb": "create",
                "object_type": "git.commit",
            },
            OPERATOR_LITERAL_PAYLOADS_CONTEXT_KEY: [
                {
                    "payload_id": "literal_payload_old",
                    "kind": "commit_message",
                    "label": "commit message",
                    "input_name": "commit_message",
                    "placeholder": "[provided commit_message payload]",
                    "value": "Old cached message",
                    "value_length": len("Old cached message"),
                    "preview": "Old cached message",
                    "source": "generated",
                }
            ],
        },
    )
    result = OperatorPipelineResult(
        status="success",
        final_response="committed",
        plan=plan,
        execution_records=[
            OperatorExecutionRecord(
                action_id=plan.actions[0].action_id,
                task_id=plan.tasks[0].task_id,
                kind="shell_command",
                status="success",
                stdout="[main abc123] Old cached message",
                stderr="",
                exit_code=0,
            )
        ],
        metadata={
            "operator_step_validation_checked": True,
            "operator_step_validation_decision": "accept",
        },
    )

    pipeline._write_streaming_step_action_tree_cache_result(request, plan, result, None)
    exact_key, _ = pipeline._lrdirect_step_metadata(request)
    candidate = cache.retrieve_exact_step_tree(
        exact_key,
        intent_signature=pipeline._streaming_step_intent_signature(
            pipeline._streaming_step_intent_snapshot(request)
        ),
    )[0]
    serialized = str(candidate.entry.direct_plan)
    assert "Old cached message" not in serialized
    assert candidate.entry.direct_plan["actions"][0]["protected_inputs"] == ["commit_message"]

    replay_request = UserRequest(
        raw_prompt=prompt,
        session_context={
            "operator_mode_label": "Conversational",
            "operator_streaming_current_task": {
                "task_id": "task_commit_new",
                "description": prompt,
                "semantic_verb": "create",
                "object_type": "git.commit",
            },
            OPERATOR_LITERAL_PAYLOADS_CONTEXT_KEY: [
                {
                    "payload_id": "literal_payload_new",
                    "kind": "commit_message",
                    "label": "commit message",
                    "input_name": "commit_message",
                    "placeholder": "[provided commit_message payload]",
                    "value": "New approved message",
                    "value_length": len("New approved message"),
                    "preview": "New approved message",
                    "source": "generated",
                }
            ],
        },
    )
    replay_plan = pipeline._streaming_step_tree_plan_from_payload(
        replay_request,
        candidate.entry.direct_plan,
        cache_id=candidate.entry.cache_id,
    )

    assert replay_plan.actions[0].inputs == {"commit_message": "New approved message"}
    assert "Old cached message" not in str(replay_plan.model_dump(mode="json"))


def test_operator_pipeline_promotes_reused_command_template_to_lrdirect(
    tmp_path: Path,
) -> None:
    prompt = "Streaming step 1 of 2: List all Docker images"
    cache = AgentCommandTemplateCacheStore(tmp_path / "command-template-cache.db")
    llm = QueueLLM()
    pipeline = _pipeline(
        tmp_path,
        llm,
        command_template_cache_store=cache,
    )
    plan = OperatorPlan.model_validate(
        _plan_payload('docker images --format "{{.Repository}}\\t{{.Tag}}\\t{{.Size}}"', cwd=str(tmp_path))
    )
    action = plan.actions[0]
    record = OperatorExecutionRecord(
        action_id=action.action_id,
        task_id=action.task_id,
        kind="shell_command",
        status="success",
        stdout="openfabric-server\tlocal\t2.43GB\nubuntu\t24.04\t119MB\n",
        stderr="",
        exit_code=0,
        metadata={"cwd": str(tmp_path)},
    )
    request = UserRequest(
        raw_prompt=prompt,
        session_context={
            "operator_mode_label": "Conversational",
            "lrdirect_enabled": True,
            "operator_command_template_cache_applied": {"template_id": "cmdtpl-existing"},
            "operator_streaming_current_task": {
                "task_id": "task_1",
                "description": "List all Docker images",
                "semantic_verb": "list",
                "object_type": "docker.image",
            },
        },
    )

    pipeline._write_command_template_cache_result(
        request,
        plan,
        action,
        record,
        {},
        None,
    )

    exact_key, _ = pipeline._lrdirect_step_metadata(request)
    candidates = cache.retrieve_exact_step(exact_key)
    assert len(candidates) == 1
    assert candidates[0].entry.direct_action["command"] == action.command
    assert "action_id" not in candidates[0].entry.direct_action
    assert "task_id" not in candidates[0].entry.direct_action
    assert "depends_on" not in candidates[0].entry.direct_action
    assert candidates[0].entry.direct_action["lrdirect_schema_version"] == 2
    assert llm.schemas == []


