    assert cache.get_entry(entry.template_id).use_count == 1  # type: ignore[union-attr]
    request.session_context.pop("operator_command_template_cache_applied", None)

    result = pipeline.execute_approved(request, plan, {"confirmation": True})

    assert result.status == "success"
    assert gateway.raw_calls[0]["command"] == "git commit -F -"
    assert gateway.raw_calls[0]["execution_context"]["shell_stdin"] == "Fresh generated message"
    assert cache.stats().total_entries == 1


