def test_operator_pipeline_lrdirect_computation_cache_strips_run_specific_ids(
    tmp_path: Path,
) -> None:
    prompt = "Streaming step 2 of 2: Calculate the total size of all Docker images in GB"
    cache = AgentComputationCacheStore(tmp_path / "computation-cache.db")
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        computation_cache_store=cache,
    )
    plan = OperatorPlan.model_validate(
        {
            "summary": "Calculate Docker image total.",
            "tasks": [
                {
                    "task_id": "task_2",
                    "goal": "Calculate the total size of all Docker images in GB",
                    "semantic_verb": "calculate",
                    "object_type": "docker.image",
                    "dependencies": ["task_1"],
                    "reason": "",
                }
            ],
            "actions": [
                {
                    "action_id": "action_old_python",
                    "task_id": "task_2",
                    "kind": "python_action",
                    "code": "def main(inputs):\n    return {'summary': inputs['docker_images_output']}",
                    "cwd": str(tmp_path),
                    "inputs": {},
                    "input_bindings": [
                        {
                            "input_name": "docker_images_output",
                            "source_action_id": "action_old_shell",
                            "source_field": "stdout",
                            "required": True,
                        }
                    ],
                    "declared_output_shape": "json",
                    "risk": "low",
                    "effect_intent": "read_only",
                    "reason": "Parse prior Docker image output.",
                }
            ],
            "dependencies": [],
            "expected_outputs": ["total"],
            "assumptions": [],
            "confidence": 1.0,
        }
    )
    action = plan.actions[0]
    record = OperatorExecutionRecord(
        action_id=action.action_id,
        task_id=action.task_id,
        kind="python_action",
        status="success",
        stdout='{"summary": "Total Docker image size: 2.55 GB"}',
        stderr="",
        exit_code=0,
        output={"summary": "Total Docker image size: 2.55 GB"},
    )
    request = UserRequest(
        raw_prompt=prompt,
        session_context={
            "lrdirect_enabled": True,
            "operator_streaming_current_task": {
                "task_id": "task_2",
                "description": "Calculate the total size of all Docker images in GB",
                "semantic_verb": "calculate",
                "object_type": "docker.image",
            },
        },
    )

    pipeline._write_computation_cache_result(
        request,
        plan,
        action,
        {"docker_images_output": "openfabric-server\tlocal\t2.43GB\n"},
        record,
        None,
    )

    exact_key, _ = pipeline._lrdirect_step_metadata(request)
    candidates = cache.retrieve_exact_step(exact_key, require_direct_action=True)
    assert len(candidates) == 1
    direct_action = candidates[0].entry.direct_action
    assert "action_id" not in direct_action
    assert "task_id" not in direct_action
    assert "depends_on" not in direct_action
    assert direct_action["lrdirect_schema_version"] == 2
    assert direct_action["input_bindings"] == [
        {
            "input_name": "docker_images_output",
            "source": "prior_streaming_result",
            "source_field": "stdout",
            "required": True,
            "fallback_value": None,
        }
    ]

    replay_request = UserRequest(
        raw_prompt=prompt,
        session_context={
            "lrdirect_enabled": True,
            "operator_streaming_current_task": {
                "task_id": "task_2",
                "description": "Calculate the total size of all Docker images in GB",
                "semantic_verb": "calculate",
                "object_type": "docker.image",
            },
            "operator_seed_records": [
                {
                    "action_id": "action_current_shell",
                    "task_id": "task_1",
                    "kind": "shell_command",
                    "status": "success",
                    "stdout": "openfabric-server\tlocal\t2.43GB\nubuntu\t24.04\t119MB\n",
                    "stderr": "",
                    "exit_code": 0,
                    "metadata": {},
                }
            ],
        },
    )
    replay_plan = pipeline._lrdirect_plan_from_action_payload(
        replay_request,
        direct_action,
        cache_type="computation",
        cache_id=candidates[0].entry.cache_id,
    )
    assert replay_plan is not None
    assert replay_plan.actions[0].input_bindings[0].source_action_id == "action_current_shell"


