def _deferred_python_plan() -> OperatorPlan:
    payload = _plan_payload("printf hello")
    payload["summary"] = "Read and compute from command output."
    payload["tasks"].append(
        {
            "task_id": "task_2",
            "goal": "Compute from command output",
            "semantic_verb": "calculate",
            "object_type": "text",
            "dependencies": ["task_1"],
            "reason": "The user wants a computed answer.",
        }
    )
    payload["actions"].append(
        {
            "action_id": "action_2",
            "task_id": "task_2",
            "kind": "python_action",
            "code": None,
            "defer_code_generation": True,
            "cwd": ".",
            "inputs": {},
            "input_bindings": [
                {
                    "input_name": "stdout",
                    "source_action_id": "action_1",
                    "source_field": "stdout",
                    "required": True,
                    "fallback_value": None,
                }
            ],
            "declared_output_shape": "text",
            "risk": "low",
            "timeout_seconds": 5,
            "reason": "Compute from fresh stdout.",
            "depends_on": [],
        }
    )
    payload["dependencies"] = [
        {
            "producer_action_id": "action_1",
            "consumer_action_id": "action_2",
            "reason": "Python parses live stdout.",
        }
    ]
    return OperatorPlan.model_validate(payload)


