def test_operator_plan_review_can_revise_valid_but_low_quality_plan(tmp_path: Path) -> None:
    initial = _plan_payload(command="docker images")
    revised = _plan_payload(command='docker images --format "{{.Repository}}:{{.Tag}} {{.Size}}"')
    llm = QueueLLM(
        initial,
        {
            **_plan_review_fields(),
            "decision": "revise",
            "revised_plan": revised,
            "verification_gap": "The original command used human-readable output that is brittle for parsing.",
            "required_revision": "Use machine-readable Docker output.",
            "issues": ["Use machine-readable Docker output when the result will be parsed."],
            "reason": "Structured output is more reliable for later formatting.",
            "confidence": 0.91,
        },
        {
            **_plan_review_fields(),
            "decision": "accept",
            "revised_plan": None,
            "reason": "The revised plan uses structured output.",
            "confidence": 0.94,
        },
    )
    pipeline = _review_pipeline(tmp_path, llm)

    plan, errors = pipeline.propose_and_validate(
        UserRequest(raw_prompt="list docker images and calculate their total size")
    )

    assert errors == []
    assert plan.actions[0].command == 'docker images --format "{{.Repository}}:{{.Tag}} {{.Size}}"'
    assert llm.schemas == [
        "OperatorSelfBrief",
        "OperatorPlan",
        "OperatorPlanReview",
        "OperatorPlanReview",
    ]
    assert "reviewing a validated" in llm.prompts[2]
    assert "strategy_alignment" in llm.prompts[2]
    assert "success_postcondition" in llm.prompts[2]


def test_operator_plan_review_has_extra_acceptance_pass_after_revisions(tmp_path: Path) -> None:
    initial = _plan_payload(command="conda env list | grep -i poop")
    first_revision = _plan_payload(command="conda env list | grep -i poop && echo failed || echo verified")
    second_revision = _plan_payload(
        command=(
            "if conda env list | grep -i poop >/dev/null; then "
            "echo failed; exit 1; else echo verified; exit 0; fi"
        )
    )
    llm = QueueLLM(
        initial,
        {
            **_plan_review_fields(),
            "decision": "revise",
            "revised_plan": first_revision,
            "verification_gap": "The original plan uses raw grep absence semantics.",
            "required_revision": "Add explicit verified/failed output.",
            "issues": ["Raw grep no-match exits nonzero for the success case."],
            "reason": "The plan needs clearer absence verification.",
            "confidence": 0.91,
        },
        {
            **_plan_review_fields(),
            "decision": "revise",
            "revised_plan": second_revision,
            "verification_gap": "The first revision still exits zero after echoing failed.",
            "required_revision": "Exit nonzero when the forbidden match still exists.",
            "issues": ["Verification must fail when the postcondition is false."],
            "reason": "The latest revision encodes success and failure explicitly.",
            "confidence": 0.94,
        },
        {
            **_plan_review_fields(),
            "decision": "accept",
            "revised_plan": None,
            "reason": "The latest reviewed plan now has explicit success and failure semantics.",
            "confidence": 0.96,
        },
    )
    pipeline = _review_pipeline(tmp_path, llm)

    plan, errors = pipeline.propose_and_validate(
        UserRequest(raw_prompt="remove conda environments with poop in the name")
    )

    assert errors == []
    assert plan.actions[0].command == second_revision["actions"][0]["command"]
    assert llm.schemas == [
        "OperatorSelfBrief",
        "OperatorPlan",
        "OperatorPlanReview",
        "OperatorPlanReview",
        "OperatorPlanReview",
    ]
    assert "Previous plan review feedback" in llm.prompts[3]
    assert "current plan fixed the previous required_revision" in llm.prompts[3]


