def test_operator_followup_plan_actions_are_checked_against_memory_directives(
    tmp_path: Path,
) -> None:
    store = AgentMemoryStore(tmp_path / "agent_memory.db")
    memory = store.create_entry(
        MemoryEntryCreate(
            instruction=(
                "Before any git add or git commit, run git rev-parse --is-inside-work-tree. "
                "If false, stop and report. Never run git init unless explicitly requested."
            ),
            summary="Check git repository before committing.",
            scope="global",
            task_type="git",
            tool_type="shell",
            intent_type="planning",
            tags=["git", "repo", "commit"],
        )
    )
    repaired_plan = _plan_payload(
        "if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then "
        "git add . && git commit -m followup; "
        "else echo 'Not a git repository'; fi"
    )
    llm = QueueLLM(
        {
            "mode": "plan_actions",
            "answer": "",
            "plan": _plan_payload("git add . && git commit -m followup"),
            "reason": "The follow-up asks for a new commit.",
            "confidence": 0.9,
        },
        _memory_compliance_payload(
            "repair_required",
            repaired_plan,
            memory_ids=[memory.memory_id],
            confidence=0.93,
        ),
    )
    pipeline = _pipeline(tmp_path, llm, memory_store=store)
    request = UserRequest(
        raw_prompt='git commit current changes with message "followup"',
        session_context={
            "operator_mode_label": "Conversational",
        },
    )

    decision = pipeline.complete_followup_decision(
        request,
        {"conversation_id": "conv-test", "turns": [{"final_response": "ready"}]},
    )

    assert decision.plan is not None
    assert "git rev-parse --is-inside-work-tree" in str(decision.plan.actions[0].command)
    assert llm.schemas == [
        "OperatorFollowupDecision",
        "MemoryComplianceReview",
    ]


