def test_execution_repair_retries_rejected_repair_until_budget(tmp_path: Path) -> None:
    failed_command = "nvidia-smi --query-memory=free --format=nounified"
    corrected_command = "nvidia-smi --query-gpu=memory.free --format=csv,noheader,nounits"
    plan = OperatorPlan.model_validate(_plan_payload(command=failed_command, cwd=str(tmp_path)))
    llm = QueueLLM(
        {
            **_repair_reasoning_fields(),
            "corrected_plan": _plan_payload(command=failed_command, cwd=str(tmp_path)),
            "retry_rationale": "Retry the same nvidia-smi query.",
            "expected_change": "The command should complete.",
            "confidence": 0.8,
        },
        {
            **_repair_reasoning_fields(),
            "corrected_plan": _plan_payload(command=corrected_command, cwd=str(tmp_path)),
            "retry_rationale": "Use the supported nvidia-smi query-gpu syntax.",
            "expected_change": "The corrected command returns free VRAM.",
            "confidence": 0.9,
        },
    )
    gateway = FailingThenSuccessOperatorGateway()
    pipeline = _pipeline(
        tmp_path,
        llm,
        gateway,
        config_overrides={"llm_operator_max_execution_repair_attempts": 2},
    )

    result = pipeline.execute_approved(UserRequest(raw_prompt="check free vram"), plan, {"confirmation": True})

