def test_execution_repair_adjudicator_rejects_semantic_bad_repair_and_retries(
    tmp_path: Path,
) -> None:
    failed_command = "resourcectl remove all"
    bad_command = "resourcectl remove all --dry-run"
    corrected_command = "resourcectl remove all --force"
    plan = OperatorPlan.model_validate(_plan_payload(command=failed_command, cwd=str(tmp_path)))
    llm = QueueLLM(
        {
            **_repair_reasoning_fields(),
            "corrected_plan": _plan_payload(command=bad_command, cwd=str(tmp_path)),
            "retry_rationale": "Run a dry-run instead of the forced removal.",
            "expected_change": "The dry-run should inspect the target.",
            "confidence": 0.74,
        },
        _repair_adjudication_payload(
            "revise_repair",
            issues=["stderr said removal must be forced; dry-run does not remove anything"],
            required_change="Use the force-required repair shown by stderr instead of a dry-run.",
            reason="The proposed command ignores the authoritative must-be-forced diagnostic.",
            confidence=0.93,
        ),
        {
            **_repair_reasoning_fields(),
            "corrected_plan": _plan_payload(command=corrected_command, cwd=str(tmp_path)),
            "retry_rationale": "Use the force option required by stderr.",
            "expected_change": "The forced removal completes.",
            "confidence": 0.9,
        },
    )
    gateway = FailingThenSuccessOperatorGateway()
    pipeline = _pipeline(
        tmp_path,
        llm,
        gateway,
        config_overrides={"llm_operator_max_execution_repair_attempts": 2},
    )

    result = pipeline.execute_approved(UserRequest(raw_prompt="remove all resources"), plan, {"confirmation": True})

    assert result.status == "success"
    assert [call["command"] for call in gateway.raw_calls] == [
        failed_command,
        corrected_command,
    ]
    assert bad_command not in [call["command"] for call in gateway.raw_calls]
    repair_prompts = [
        prompt for schema, prompt in zip(llm.schemas, llm.prompts) if schema == "OperatorRepair"
    ]
    assert len(repair_prompts) == 2
    assert "execution_repair_adjudication_rejected" in repair_prompts[1]
    assert "must-be-forced diagnostic" in repair_prompts[1]


