def _write_resourcectl_fixture(tmp_path: Path) -> tuple[dict[str, str], Path]:
    bin_dir = tmp_path / "bin"
    bin_dir.mkdir()
    state_path = tmp_path / "resource_state.txt"
    state_path.write_text("blocked\n", encoding="utf-8")
    script = bin_dir / "resourcectl"
    script.write_text(
        "\n".join(
            [
                "#!/usr/bin/env python3",
                "import json",
                "import sys",
                "from pathlib import Path",
                f"state = Path({str(state_path)!r})",
                "args = sys.argv[1:]",
                "status = state.read_text(encoding='utf-8').strip()",
                "if args == ['remove', 'all']:",
                "    print('resource conflict: unable to remove target alpha (must be forced) - target is held by inactive blocker beta', file=sys.stderr)",
                "    sys.exit(1)",
                "if args == ['list', '--json']:",
                "    print(json.dumps({'id': 'alpha', 'status': status, 'blocker': 'beta'}))",
                "    sys.exit(0)",
                "if args == ['blocker', 'remove', 'beta']:",
                "    state.write_text('unblocked\\n', encoding='utf-8')",
                "    print('blocker removed')",
                "    sys.exit(0)",
                "if args == ['remove', 'all', '--force']:",
                "    if state.read_text(encoding='utf-8').strip() != 'unblocked':",
                "        print('blocker beta still present', file=sys.stderr)",
                "        sys.exit(1)",
                "    state.write_text('removed\\n', encoding='utf-8')",
                "    print('removed')",
                "    sys.exit(0)",
                "print('usage: resourcectl list --json | blocker remove beta | remove all [--force]', file=sys.stderr)",
                "sys.exit(2)",
            ]
        ),
        encoding="utf-8",
    )
    script.chmod(0o755)
    env = {"PATH": f"{bin_dir}{os.pathsep}{os.environ.get('PATH', '')}"}
    return env, state_path


def _run_live_resource_repair_budget_case(tmp_path: Path, budget: int) -> dict[str, Any]:
    case_dir = tmp_path / f"budget_{budget}"
    case_dir.mkdir()
    env, state_path = _write_resourcectl_fixture(case_dir)
    original_payload = _plan_payload(command="resourcectl remove all", cwd=str(case_dir))
    original_payload["summary"] = "Remove all resources."
    original_payload["tasks"][0].update(
        {
            "goal": "Remove all resources",
            "semantic_verb": "delete",
            "object_type": "resource",
        }
    )
    original_payload["actions"][0].update(
        {
            "risk": "high",
            "effect_intent": "mutates_state",
            "effect_summary": "Remove all resources.",
            "reason": "Remove all resources.",
        }
    )
    bad_payload = _plan_payload(command="resourcectl remove all --dry-run", cwd=str(case_dir))
    responses: list[dict[str, Any]] = [
        {
            **_repair_reasoning_fields(),
            "corrected_plan": bad_payload,
            "retry_rationale": "Try a dry-run after the failure.",
            "expected_change": "The dry-run should inspect the resource state.",
            "confidence": 0.72,
        },
        _repair_adjudication_payload(
            "revise_repair",
            issues=["dry-run ignores the stderr instruction that removal must be forced"],
            required_change="Inspect the resource state, remove blocker beta, and use --force.",
            reason="The proposed repair does not pursue the trace-grounded forced removal.",
            confidence=0.94,
        ),
    ]
    if budget >= 2:
        responses.append(
            {
                **_repair_reasoning_fields(),
                "corrected_plan": _resource_cleanup_repair_payload(str(case_dir)),
                "root_cause": "The remove command failed because blocker beta held target alpha.",
                "evidence_from_stdout_stderr": (
                    "resource conflict: unable to remove target alpha (must be forced)"
                ),
                "required_change": "Remove blocker beta, then run resourcectl remove all --force.",
                "retry_rationale": "Follow the forced-removal diagnostic from stderr.",
                "expected_change": "The approved repair removes the blocker and then the target.",
                "confidence": 0.95,
            }
        )
    llm = QueueLLM(*responses)
    gateway = LocalPathOperatorGateway(env=env)
    pipeline = _pipeline(
        case_dir,
        llm,
        gateway,
        config_overrides={"llm_operator_max_execution_repair_attempts": budget},
    )
    started = time.monotonic()
    result = pipeline.execute_approved(
        UserRequest(raw_prompt="list all resources and remove all resources"),
        OperatorPlan.model_validate(original_payload),
        {"confirmation": True},
    )
    attempts_used = llm.schemas.count("OperatorRepair")
    if result.status == "confirmation_required":
        result = pipeline.execute_approved(
            UserRequest(raw_prompt="list all resources and remove all resources"),
            result.plan,
            {
                "confirmation": True,
                "operator_seed_records": [
                    record.model_dump(mode="json") for record in result.execution_records
                ],
                "operator_execution_repair_attempted": True,
                "operator_execution_repair_attempt_count": attempts_used,
            },
        )
    duration_ms = (time.monotonic() - started) * 1000.0
    raw_commands = [call["command"] for call in gateway.raw_calls]
    return {
        "budget": budget,
        "success": result.status == "success" and state_path.read_text(encoding="utf-8").strip() == "removed",
        "false_accept": "resourcectl remove all --dry-run" in raw_commands,
        "attempts_used": attempts_used,
        "llm_calls": len(llm.schemas),
        "duration_ms": duration_ms,
        "commands": raw_commands,
        "status": result.status,
    }


def test_execution_repair_live_resourcectl_budget_sweep_recommends_two_attempts(
    tmp_path: Path,
) -> None:
    results = [
        _run_live_resource_repair_budget_case(tmp_path, budget)
        for budget in (1, 2, 3, 4)
    ]
    recommendation = recommend_execution_repair_budget(
        results,
        target_success_rate=1.0,
        max_false_accept_rate=0.0,
    )

    assert recommendation["recommended_budget"] == 2
    assert results[0]["success"] is False
    assert all(result["success"] for result in results[1:])
    assert not any(result["false_accept"] for result in results)
    assert results[1]["commands"] == [
        "resourcectl remove all",
        "resourcectl list --json",
        "resourcectl blocker remove beta",
        "resourcectl remove all --force",
    ]


