def test_execution_learning_digest_proposes_memory_after_corrected_shell_command(
    tmp_path: Path,
) -> None:
    failed_command = "nvidia-smi --query-memory=free --format=nounified"
    successful_command = "nvidia-smi --query-gpu=memory.free --format=csv,noheader,nounits"
    failed_plan = _plan_payload(command=failed_command, cwd=str(tmp_path))
    failed_plan["tasks"][0]["goal"] = "Check the amount of free VRAM in the GPU"
    failed_plan["tasks"][0]["object_type"] = "gpu.vram"
    repaired_plan = _plan_payload(command=successful_command, cwd=str(tmp_path))
    repaired_plan["tasks"][0]["goal"] = "Check the amount of free VRAM in the GPU"
    repaired_plan["tasks"][0]["object_type"] = "gpu.vram"
    llm = QueueLLM(
        {
            **_repair_reasoning_fields(),
            "corrected_plan": repaired_plan,
            "retry_rationale": "Use the supported nvidia-smi query-gpu syntax.",
            "expected_change": "The command returns free VRAM.",
            "confidence": 0.9,
        }
    )
    store = AgentMemoryStore(tmp_path / "agent_memory.db")
    gateway = DiagnosticThenCorrectedShellGateway(
        failed_command=failed_command,
        successful_command=successful_command,
    )
    sink = InMemoryEventSink()
    observability = build_observability_context(
        "req-exec-learning",
        {"observability": {"enabled": True, "debug": True, "sinks": [sink]}},
    )
    pipeline = _pipeline(
        tmp_path,
        llm,
        gateway,
        config_overrides={
            "llm_operator_final_response_mode": "simple",
            "llm_operator_max_completion_repair_attempts": 0,
        },
        memory_store=store,
    )
    request = UserRequest(
        request_id="req-exec-learning",
        raw_prompt="check the amount of free vram in my GPU",
    )

    result = pipeline.execute_approved(
        request,
        OperatorPlan.model_validate(failed_plan),
        {"confirmation": True},
        observability,
    )

    assert result.status == "success"
    assert [call["command"] for call in gateway.raw_calls] == [failed_command, successful_command]
    proposals = store.list_proposals()
    assert len(proposals) == 1
    draft = proposals[0].draft
    assert draft["memory_kind"] == "task_memory"
    assert draft["provenance"] == "feedback"
    assert draft["safe_examples"] == [successful_command]
    assert draft["blocked_examples"] == [failed_command]
    assert "do not use" in draft["instruction"].lower()
    assert any(str(tag).startswith("execdigest") for tag in draft["tags"])
    assert result.metadata["operator_memory_digest_proposals"][0]["proposal_id"] == proposals[0].proposal_id
    digest_events = [event for event in sink.events if event.event_type == OPERATOR_MEMORY_DIGEST_PROPOSED]
    assert len(digest_events) == 1
    assert digest_events[0].details["proposal_id"] == proposals[0].proposal_id


