def test_execution_learning_digest_dedupes_repeated_corrections(tmp_path: Path) -> None:
    failed_command = "nvidia-smi --query-memory=free --format=nounified"
    successful_command = "nvidia-smi --query-gpu=memory.free --format=csv,noheader,nounits"
    store = AgentMemoryStore(tmp_path / "agent_memory.db")

    for index in range(2):
        failed_plan = _plan_payload(command=failed_command, cwd=str(tmp_path))
        failed_plan["tasks"][0]["goal"] = "Check the amount of free VRAM in the GPU"
        repaired_plan = _plan_payload(command=successful_command, cwd=str(tmp_path))
        repaired_plan["tasks"][0]["goal"] = "Check the amount of free VRAM in the GPU"
        llm = QueueLLM(
            {
                **_repair_reasoning_fields(),
                "corrected_plan": repaired_plan,
                "retry_rationale": "Use the supported nvidia-smi query-gpu syntax.",
                "expected_change": "The command returns free VRAM.",
                "confidence": 0.9,
            }
        )
        pipeline = _pipeline(
            tmp_path,
            llm,
            DiagnosticThenCorrectedShellGateway(
                failed_command=failed_command,
                successful_command=successful_command,
            ),
            config_overrides={
                "llm_operator_final_response_mode": "simple",
                "llm_operator_max_completion_repair_attempts": 0,
            },
            memory_store=store,
        )

        result = pipeline.execute_approved(
            UserRequest(
                request_id=f"req-exec-learning-{index}",
                raw_prompt="check the amount of free vram in my GPU",
            ),
            OperatorPlan.model_validate(failed_plan),
            {"confirmation": True},
        )

        assert result.status == "success"

    assert len(store.list_proposals()) == 1


