def test_typed_llm_stdout_error_judge_can_mark_ambiguous_stdout_as_error(tmp_path: Path) -> None:
    plan = OperatorPlan.model_validate(_plan_payload(command="custom-tool --json", cwd=str(tmp_path)))
    llm = QueueLLM({"is_error": True, "confidence": 0.9})
    pipeline = _pipeline(
        tmp_path,
        llm,
        FixedShellResultGateway(stdout="operation aborted before producing requested data\n", exit_code=3),
        config_overrides={"operator_stdout_policy_mode": "llm"},
    )

    result = pipeline.execute_approved(UserRequest(raw_prompt="run custom tool"), plan, {"confirmation": True})

    assert result.status == "error"
    assert result.execution_records[0].status == "error"
    assert result.execution_records[0].metadata["stdout_diagnostic_error"] is True
    assert result.execution_records[0].metadata["stdout_error_classifier"]["classifier_source"] == "llm"
    assert llm.schemas[0] == "SudoRetryJudge"
    assert llm.schemas[1] == "ShellStdoutErrorJudge"
    assert llm.schemas.count("ShellStdoutErrorJudge") == 1


