def test_stdout_error_judge_is_cached_per_request(tmp_path: Path) -> None:
    llm = QueueLLM({"is_error": True, "confidence": 0.9})
    pipeline = _pipeline(tmp_path, llm, config_overrides={"operator_stdout_policy_mode": "llm"})
    request = UserRequest(raw_prompt="run custom tool")

    first = pipeline._classify_shell_stdout_after_nonzero_exit(
        user_request=request,
        action_kind="shell_command",
        command="custom-tool --json",
        exit_code=3,
        stdout="operation aborted before producing requested data\n",
        stderr="",
        command_cancelled=False,
        macro_delivery_failed=False,
    )
    second = pipeline._classify_shell_stdout_after_nonzero_exit(
        user_request=request,
        action_kind="shell_command",
        command="custom-tool --json",
        exit_code=3,
        stdout="operation aborted before producing requested data\n",
        stderr="",
        command_cancelled=False,
        macro_delivery_failed=False,
    )

    assert first.stdout_usable is False
    assert second.stdout_usable is False
    assert second.classifier_source == "llm_cached"
    assert llm.schemas == ["ShellStdoutErrorJudge"]


