def test_stdout_only_shell_nonzero_result_is_success_under_stdout_primary_rule(tmp_path: Path) -> None:
    original_plan_payload = {
        "summary": "Stage changes and verify the staged state.",
        "tasks": [
            {
                "task_id": "task_1",
                "goal": "Stage all pending changes",
                "semantic_verb": "update",
                "object_type": "git.index",
                "dependencies": [],
                "reason": "The user requested staging changes.",
            },
            {
                "task_id": "task_2",
                "goal": "Verify changes were staged",
                "semantic_verb": "analyze",
                "object_type": "git.index",
                "dependencies": ["task_1"],
                "reason": "Verification should prove the requested staging happened.",
            },
        ],
        "actions": [
            {
                "action_id": "action_1",
                "task_id": "task_1",
                "kind": "shell_command",
                "command": "git add .",
                "cwd": ".",
                "inputs": {},
                "input_bindings": [],
                "declared_output_shape": "text",
                "risk": "high",
                "reason": "Stage all pending changes.",
                "depends_on": [],
            },
            {
                "action_id": "action_2",
                "task_id": "task_2",
                "kind": "shell_command",
                "command": (
                    "if [ -z \"$(git status --porcelain)\" ]; then "
                    "echo 'verified'; else echo 'failed'; exit 1; fi"
                ),
                "cwd": ".",
                "inputs": {},
                "input_bindings": [],
                "declared_output_shape": "text",
                "risk": "low",
                "reason": "Verify staging.",
                "depends_on": ["action_1"],
            },
        ],
        "dependencies": [
            {
                "producer_action_id": "action_1",
                "consumer_action_id": "action_2",
                "reason": "Verify after staging.",
            }
        ],
        "expected_outputs": ["staged changes verified"],
        "assumptions": [],
        "confidence": 0.9,
    }
    repaired_plan_payload = dict(original_plan_payload)
    repaired_plan_payload["actions"] = [
        original_plan_payload["actions"][0],
        {
            **original_plan_payload["actions"][1],
            "command": "git diff --quiet && echo verified",
            "risk": "high",
            "reason": "Verify that no unstaged changes remain after staging.",
        },
    ]
    llm = QueueLLM(
        {
            **_repair_reasoning_fields(),
            "corrected_plan": repaired_plan_payload,
            "retry_rationale": "The original verifier confused a clean tree with a fully staged tree.",
            "expected_change": "The repaired verifier checks unstaged changes directly.",
            "confidence": 0.9,
        }
    )
    pipeline = _pipeline(tmp_path, llm, StdoutOnlyVerifierFailureGateway())
    plan = OperatorPlan.model_validate(original_plan_payload)

    result = pipeline.execute_approved(
        UserRequest(
            raw_prompt="stage all changes in this branch",
            session_context={"operator_mode_label": "Agent"},
        ),
        plan,
        {"confirmation": True},
    )

    assert result.status == "success"
    assert result.confirmation_required is False
    assert result.execution_records[1].stdout == "failed\n"
    assert result.execution_records[1].status == "success"
    assert result.execution_records[1].metadata["partial_stdout_available"] is True
    assert result.execution_records[1].metadata["stdout_primary_success"] is True
    assert result.metadata.get("operator_execution_repair_pending") is not True


def test_execution_repair_confirmation_resumes_after_completed_commit_steps(tmp_path: Path) -> None:
    original_plan_payload = {
        "summary": "Stage, commit, and push changes.",
        "tasks": [
            {
                "task_id": "task_1",
                "goal": "Verify git repository",
                "semantic_verb": "analyze",
                "object_type": "git.repository",
                "dependencies": [],
                "reason": "Git operations require a repository.",
            },
            {
                "task_id": "task_2",
                "goal": "Stage all changes",
                "semantic_verb": "update",
                "object_type": "git.index",
                "dependencies": ["task_1"],
                "reason": "The user asked to stage changes.",
            },
            {
                "task_id": "task_3",
                "goal": "Commit staged changes",
                "semantic_verb": "create",
                "object_type": "git.commit",
                "dependencies": ["task_2"],
                "reason": "The user provided a commit message.",
            },
            {
                "task_id": "task_4",
                "goal": "Push committed changes",
                "semantic_verb": "update",
                "object_type": "git.remote",
                "dependencies": ["task_3"],
                "reason": "The user asked to push the changes.",
            },
        ],
        "actions": [
            {
                "action_id": "action_1",
                "task_id": "task_1",
                "kind": "shell_command",
                "command": "git rev-parse --is-inside-work-tree",
                "cwd": ".",
                "inputs": {},
                "input_bindings": [],
                "declared_output_shape": "text",
                "risk": "low",
                "reason": "Verify that the current directory is a Git work tree.",
                "depends_on": [],
            },
            {
                "action_id": "action_2",
                "task_id": "task_2",
                "kind": "shell_command",
                "command": "git add .",
                "cwd": ".",
                "inputs": {},
                "input_bindings": [],
                "declared_output_shape": "text",
                "risk": "medium",
                "reason": "Stage all changes.",
                "depends_on": ["action_1"],
            },
            {
                "action_id": "action_3",
                "task_id": "task_3",
                "kind": "shell_command",
                "command": "git commit -F -",
                "cwd": ".",
                "inputs": {},
                "input_bindings": [],
                "stdin_mode": "literal",
                "stdin_text": "Fix Deep Reasoning mode sync\n",
                "declared_output_shape": "text",
                "risk": "high",
                "reason": "Commit staged changes with the provided message.",
                "depends_on": ["action_2"],
            },
            {
                "action_id": "action_4",
                "task_id": "task_4",
                "kind": "shell_command",
                "command": "git push",
                "cwd": ".",
                "inputs": {},
                "input_bindings": [],
                "declared_output_shape": "text",
                "risk": "high",
                "reason": "Push committed changes.",
                "depends_on": ["action_3"],
            },
        ],
        "dependencies": [
            {"producer_action_id": "action_1", "consumer_action_id": "action_2", "reason": "Repository proof before staging."},
            {"producer_action_id": "action_2", "consumer_action_id": "action_3", "reason": "Commit after staging."},
            {"producer_action_id": "action_3", "consumer_action_id": "action_4", "reason": "Push after commit."},
        ],
        "expected_outputs": ["changes committed and pushed"],
        "assumptions": [],
        "confidence": 0.9,
    }
    repaired_plan_payload = dict(original_plan_payload)
    repaired_plan_payload["actions"] = [
        *original_plan_payload["actions"][:3],
            {
                **original_plan_payload["actions"][3],
                "command": "git push --set-upstream origin HEAD",
                "reason": "Push the committed changes and set upstream tracking.",
            },
    ]
    llm = QueueLLM(
        {
            **_repair_reasoning_fields(),
            "corrected_plan": repaired_plan_payload,
            "retry_rationale": "The push failed because the branch had no upstream.",
            "expected_change": "Only the push command needs to be retried with upstream setup.",
            "confidence": 0.9,
        }
    )

    class GitPushNeedsUpstreamGateway(FakeOperatorGateway):
        def execute_raw_command(
            self,
            *,
            command: str,
            cwd: str,
            execution_context: dict[str, Any] | None = None,
        ) -> dict[str, Any]:
            self.raw_calls.append(
                {"command": command, "cwd": cwd, "execution_context": dict(execution_context or {})}
            )
            if command == "git rev-parse --is-inside-work-tree":
                return {"stdout": "true\n", "stderr": "", "exit_code": 0, "gateway_node": "fake"}
            if command == "git add .":
                return {"stdout": "", "stderr": "", "exit_code": 0, "gateway_node": "fake"}
            if command == "git commit -F -":
                return {"stdout": "[V14_viceroy abc123] fix\n", "stderr": "", "exit_code": 0, "gateway_node": "fake"}
            if command == "git push":
                return {
                    "stdout": "",
                    "stderr": "fatal: The current branch V14_viceroy has no upstream branch.\n",
                    "exit_code": 128,
                    "gateway_node": "fake",
                }
            if command == "git push --set-upstream origin HEAD":
                return {
                    "stdout": "branch 'V14_viceroy' set up to track 'origin/V14_viceroy'.\n",
                    "stderr": "",
                    "exit_code": 0,
                    "gateway_node": "fake",
                }
            raise AssertionError(f"unexpected command: {command}")

        def stream_terminal_command(
            self,
            *,
            command: str,
            cwd: str,
            execution_context: dict[str, Any] | None = None,
            display_command: str | None = None,
        ) -> list[dict[str, Any]]:
            self.raw_calls.append(
                {"command": command, "cwd": cwd, "execution_context": dict(execution_context or {})}
            )
            if command == "git push":
                return [
                    {
                        "type": "stderr",
                        "text": "fatal: The current branch V14_viceroy has no upstream branch.\n",
                        "gateway_node": "fake",
                        "terminal_dispatch": True,
                    },
                    {"type": "completed", "exit_code": 128, "gateway_node": "fake", "terminal_dispatch": True},
                ]
            if command == "git push --set-upstream origin HEAD":
                return [
                    {
                        "type": "stdout",
                        "text": "branch 'V14_viceroy' set up to track 'origin/V14_viceroy'.\n",
                        "gateway_node": "fake",
                        "terminal_dispatch": True,
                    },
                    {"type": "completed", "exit_code": 0, "gateway_node": "fake", "terminal_dispatch": True},
                ]
            raise AssertionError(f"unexpected terminal command: {command}")

    gateway = GitPushNeedsUpstreamGateway()
    pipeline = _pipeline(
        tmp_path,
        llm,
        gateway,
        config_overrides={
            "llm_operator_max_completion_repair_attempts": 0,
            "terminal_execution_enabled": True,
            "terminal_session_id": "term-test",
            "terminal_cwd": str(tmp_path),
        },
    )
    plan = OperatorPlan.model_validate(original_plan_payload)

    pending = pipeline.execute_approved(
        UserRequest(raw_prompt="stage all changes, commit them, and push"),
        plan,
        {"confirmation": True, "terminal_session_id": "term-test"},
    )

    assert pending.status == "confirmation_required"
    assert pending.metadata["operator_execution_repair_pending"] is True
    assert [record.action_id for record in pending.execution_records] == [
        "action_1",
        "action_2",
        "action_3",
    ]
    assert [action["node_id"] for action in pending.confirmation_actions] == ["action_4"]
    assert "### Already Completed" in pending.final_response
    assert "git push --set-upstream origin HEAD" in pending.final_response
    assert "Command:\n    ```bash\ngit push\n" not in pending.final_response

    resumed = pipeline.execute_approved(
        UserRequest(raw_prompt="stage all changes, commit them, and push"),
        pending.plan,
        {
            "confirmation": True,
            "operator_seed_records": [
                record.model_dump(mode="json") for record in pending.execution_records
            ],
            "operator_execution_repair_attempted": True,
            "operator_execution_repair_attempt_count": pending.metadata[
                "operator_execution_repair_attempt_count"
            ],
            "terminal_session_id": "term-test",
        },
    )

    assert resumed.status == "success"
    assert [call["command"] for call in gateway.raw_calls] == [
        "git rev-parse --is-inside-work-tree",
        "git add .",
        "git commit -F -",
        "git push",
        "git push --set-upstream origin HEAD",
    ]


def test_execution_repair_rejects_duplicate_completed_mutation(tmp_path: Path) -> None:
    original_payload = _plan_payload(command="printf mutate")
    original_payload["actions"][0]["risk"] = "high"
    duplicate_payload = _plan_payload(command="printf mutate")
    duplicate_payload["actions"][0]["action_id"] = "action_2"
    duplicate_payload["actions"][0]["risk"] = "high"
    original_plan = OperatorPlan.model_validate(original_payload)
    repaired_plan = OperatorPlan.model_validate(duplicate_payload)
    record = OperatorExecutionRecord(
        action_id="action_1",
        task_id="task_1",
        kind="shell_command",
        status="success",
        stdout="done\n",
        stderr="",
        exit_code=0,
        output=None,
        error=None,
        metadata={},
    )
    pipeline = _pipeline(tmp_path, QueueLLM())

    errors = pipeline._execution_repair_completed_mutation_errors(
        original_plan,
        repaired_plan,
        [record],
        [],
    )

    assert errors
    assert errors[0]["error"] == "execution_repair_duplicates_completed_mutation"


