def test_memory_prompt_lines_are_filtered_by_stage() -> None:
    request = _stage_memory_request()
    trace = PlanningTrace(request_id="req-memory-stage", raw_prompt=request.raw_prompt)
    request.safety_context["planning_trace"] = trace

    plan_directives = memory_directives_for_prompt_stage(request, stage="operator_plan")
    final_directives = memory_directives_for_prompt_stage(request, stage="final_answer")
    cache_directives = memory_directives_for_prompt_stage(request, stage="cache")
    classification_directives = memory_directives_for_prompt_stage(
        request,
        stage="classification",
    )

    assert [directive["memory_id"] for directive in plan_directives] == ["mem_plan"]
    assert [directive["memory_id"] for directive in final_directives] == ["mem_answer"]
    assert [directive["memory_id"] for directive in cache_directives] == ["mem_plan"]
    assert classification_directives == []
    assert request.session_context["agent_memory_rendered_stage_ids"]["operator_plan"] == [
        "mem_plan"
    ]
    assert request.session_context["agent_memory_filtered_stage_ids"]["classification"] == [
        "mem_plan",
        "mem_answer",
    ]
    assert request.session_context["agent_memory_stage_filter_notes"]["classification"][
        "filtered_count"
    ] == 2
    assert trace.metadata["agent_memory_rendered_stage_ids"]["operator_plan"] == ["mem_plan"]
    assert (
        trace.metadata["agent_memory_stage_filter_notes"]["classification"]["filtered_count"] == 2
    )


