def test_operator_memory_check_event_closes_profiler_stage(tmp_path: Path) -> None:
    pipeline = _pipeline(tmp_path, QueueLLM())
    profiler = RuntimeProfiler("req-memory-profile")
    observability = build_observability_context(
        "req-memory-profile",
        {
            "observability": {
                "enabled": True,
                "debug": True,
                "sinks": [InMemoryEventSink()],
            },
            "runtime_profiler": profiler,
        },
    )
    request = UserRequest(raw_prompt="stage and commit")

    pipeline._emit_memory_check(
        request,
        observability,
        title="Memory check completed",
        summary="Memory retrieval completed.",
        details={"memory_count": 0},
    )

    assert profiler._active_stages == {}
    assert profiler.stage_timings[-1]["stage"] == "memory_check"
    assert profiler.stage_timings[-1]["duration_ms"] >= 0


def test_memory_guard_checks_python_and_action_intent_text(tmp_path: Path) -> None:
    from agent_runtime.operator.pipeline import _memory_constraint_errors

    payload = _plan_payload(command="python stage.py", cwd=str(tmp_path))
    payload["actions"][0].update(
        {
            "kind": "python_action",
            "command": None,
            "code": "def main(inputs):\n    import subprocess\n    subprocess.run('git add .', shell=True)",
            "reason": "Run git add from Python.",
        }
    )
    directive = {
        "memory_id": "mem_git_repo_guard",
        "instruction": (
            "Before git add or git commit, prove the directory is a Git work tree "
            "with git rev-parse --is-inside-work-tree."
        ),
        "memory_kind": "task_memory",
        "applies_to": ["plan_review", "operator_plan"],
        "strength": "required_unless_conflict",
        "summary": "Check repo before git add.",
    }

    errors = _memory_constraint_errors(
        UserRequest(raw_prompt="stage changes"),
        OperatorPlan.model_validate(payload),
        [directive],
    )

    assert errors
