def test_memory_prompt_stage_filtering_covers_operator_prompt_surfaces(
    tmp_path: Path,
) -> None:
    request = UserRequest(
        raw_prompt="stage all git changes",
        session_context={
            "agent_memory": [
                {
                    "memory_id": "mem_plan",
                    "instruction": "Verify the exact user-requested postcondition.",
                    "summary": "Postcondition verification",
                    "scope": "global",
                    "tags": ["git", "verification"],
                },
                {
                    "memory_id": "mem_answer",
                    "instruction": "Answer exactly with a compact final markdown table.",
                    "summary": "Final answer formatting",
                    "scope": "global",
                    "tags": ["answer", "format"],
                },
            ]
        },
    )
    cache = AgentPlanCacheStore(tmp_path / "plan-cache.db")
    cache.upsert_entry(
        PlanCacheWrite(
            prompt="stage all git changes",
            mode="Conversational",
            model_name="fake-operator",
            tool_type="shell",
            tags=["git", "stage"],
            plan=_plan_payload("git add ."),
            status="success",
        )
    )
    candidate = cache.retrieve(
        PlanCacheLookupContext(
            prompt="stage all git changes",
            mode="Conversational",
            model_name="fake-operator",
            tool_type="shell",
            tags=["git", "stage"],
        )
    )[0]

    cache_prompt = build_operator_plan_cache_prompt(request, candidate)
    plan_review_prompt = build_operator_plan_review_prompt(
        request,
        OperatorPlan.model_validate(_plan_payload("git add .")),
    )
    clarification_prompt = build_operator_clarification_prompt(request)
    direct_prompt = AgentRuntime.__new__(AgentRuntime)._build_direct_answer_prompt(request)
    classification_prompt = _build_classification_prompt(request, build_default_registry())
    classification = PromptClassification(
        prompt_type="simple_tool_task",
        requires_tools=True,
        likely_domains=["operator"],
        risk_level="medium",
        needs_clarification=False,
        reason="The request changes local git state.",
    )
    decomposition_prompt = _build_decomposition_prompt(
        request,
        classification,
        registry=build_default_registry(),
    )
    machine_prompt = _machine_plan_prompt(request)
    code_llm = QueueLLM(
        {
            "code": "def main(inputs):\n    return inputs.get('stdout', '')",
            "declared_output_shape": "text",
            "reason": "Return parsed stdout.",
            "confidence": 0.9,
        }
    )
    action = OperatorAction.model_validate(
        {
            **_plan_payload(cwd=str(tmp_path))["actions"][0],
            "kind": "python_action",
            "command": None,
            "code": None,
            "defer_code_generation": True,
        }
    )
    _pipeline(tmp_path, code_llm)._complete_deferred_python_code(
        request,
        action,
        {"stdout": "ok"},
        None,
    )
    code_prompt = code_llm.prompts[0]

    assert "Verify the exact user-requested postcondition" in cache_prompt
    assert "Answer exactly with a compact final markdown table" not in cache_prompt
    assert "Verify the exact user-requested postcondition" in plan_review_prompt
    assert "Answer exactly with a compact final markdown table" not in plan_review_prompt
    assert "Answer exactly with a compact final markdown table" in clarification_prompt
    assert "Verify the exact user-requested postcondition" not in clarification_prompt
    assert "Answer exactly with a compact final markdown table" in direct_prompt
    assert "Verify the exact user-requested postcondition" not in direct_prompt
    assert (
        "User-approved persistent memory constraints for this request"
        not in classification_prompt
    )
    assert (
        "User-approved persistent memory constraints for this request"
        not in decomposition_prompt
    )
    assert "Verify the exact user-requested postcondition" in machine_prompt
    assert "Answer exactly with a compact final markdown table" not in machine_prompt
    assert "Verify the exact user-requested postcondition" in code_prompt
    assert "Answer exactly with a compact final markdown table" not in code_prompt


def test_operator_memory_is_refreshed_after_self_brief_classification(tmp_path: Path) -> None:
    store = AgentMemoryStore(tmp_path / "agent_memory.db")
    git_memory = store.create_entry(
        MemoryEntryCreate(
            instruction="For git staging, verify with git diff --cached.",
            summary="Git staging verification.",
            scope="global",
            task_type="git",
            tool_type="shell",
            intent_type="verify_state",
            tags=["git", "staging"],
        )
    )
    docker_memory = store.create_entry(
        MemoryEntryCreate(
            instruction="For Docker image sizes, parse each image row and convert units before summing.",
            summary="Docker image size parsing.",
            scope="global",
            task_type="docker",
            tool_type="shell",
            intent_type="calculate_size",
            tags=["docker", "images", "size"],
        )
    )
    llm = QueueLLM()
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            gateway_timeout_seconds=30,
            llm_operator_self_brief_mode="always",
        ),
        result_store=InMemoryResultStore(),
        memory_store=store,
    )
    request = UserRequest(
        raw_prompt="list all docker images and calculate total size in GB",
        session_context={
            "agent_memory": [git_memory.model_dump(mode="json")],
        },
    )

    pipeline._ensure_self_brief(request)

    assert "For git staging" not in llm.prompts[0]
    assert request.session_context["agent_memory_retrieved_after_self_brief"] is True
    applied_ids = [entry["memory_id"] for entry in request.session_context["agent_memory"]]
    assert applied_ids == [docker_memory.memory_id]
    assert store.get_entry(git_memory.memory_id).use_count == 0  # type: ignore[union-attr]
    assert store.get_entry(docker_memory.memory_id).use_count == 1  # type: ignore[union-attr]


