def test_operator_memory_compliance_repairs_git_commit_without_repo_check(tmp_path: Path) -> None:
    store = AgentMemoryStore(tmp_path / "agent_memory.db")
    memory = store.create_entry(
        MemoryEntryCreate(
            instruction=(
                "Before any git add or git commit, run git rev-parse --is-inside-work-tree. "
                "If false, stop and report. Never run git init unless explicitly requested."
            ),
            summary="Check git repository before committing.",
            scope="global",
            task_type="git",
            tool_type="shell",
            intent_type="planning",
            tags=["git", "repo", "commit"],
        )
    )
    unsafe_plan = _plan_payload("git add . && git commit -m memory-test")
    repaired_plan = _plan_payload(
        "if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then "
        "git add . && git commit -m memory-test; "
        "else echo 'Not a git repository'; fi"
    )
    llm = QueueLLM(
        unsafe_plan,
        {
            "decision": "accept",
            "revised_plan": None,
            **_plan_review_fields(),
            "issues": [],
            "reason": "The plan is otherwise valid.",
            "confidence": 0.9,
        },
        _memory_compliance_payload(
            "repair_required",
            repaired_plan,
            memory_ids=[memory.memory_id],
            confidence=0.92,
        ),
    )
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            gateway_timeout_seconds=30,
        ),
        result_store=InMemoryResultStore(),
        memory_store=store,
    )
    request = UserRequest(raw_prompt='git commit the current changes with message "memory-test"')

    plan, errors = pipeline.propose_and_validate(request)

    assert errors == []
    assert "git rev-parse --is-inside-work-tree" in str(plan.actions[0].command)
    assert "git init" not in str(plan.actions[0].command)
    assert "MemoryComplianceReview" in llm.schemas
    assert request.session_context["agent_memory_directives"][0]["memory_id"] == memory.memory_id


def test_memory_compliance_invalid_revision_goes_through_normal_repair(tmp_path: Path) -> None:
    directive = {
        "memory_id": "mem_git_guard",
        "instruction": (
            "Before any git add or git commit, run git rev-parse --is-inside-work-tree. "
            "If false, stop and report. Never run git init unless explicitly requested."
        ),
        "memory_kind": "task_memory",
        "applies_to": ["plan_review", "operator_plan"],
        "strength": "required_unless_conflict",
        "summary": "Check git repository before committing.",
        "safe_examples": [],
        "blocked_examples": [],
        "match_reasons": ["test"],
        "score": 300,
    }
    original_plan = OperatorPlan.model_validate(_plan_payload("git add . && git commit -m generated"))
    invalid_revision = _plan_payload(
        "if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then "
        "git add . && git commit -m generated; "
        "else echo 'Not a git repository'; fi"
    )
    invalid_revision["tasks"].append(
        {
            "task_id": "task_2",
            "goal": "Summarize the reviewed diff",
            "semantic_verb": "generate",
            "object_type": "text",
            "dependencies": [],
            "reason": "Produce a concise commit summary.",
        }
    )
    invalid_revision["actions"].append(
        {
            "action_id": "action_2",
            "task_id": "task_2",
            "kind": "python_action",
            "command": None,
            "code": "import subprocess\n\ndef main(inputs):\n    return 'generated summary'",
            "cwd": ".",
            "inputs": {},
            "input_bindings": [],
            "declared_output_shape": "text",
            "risk": "low",
            "timeout_seconds": 5,
            "reason": "Generate a summary.",
            "depends_on": [],
        }
    )
    repaired_revision = dict(invalid_revision)
    repaired_revision["actions"] = [dict(action) for action in invalid_revision["actions"]]
    repaired_revision["actions"][1] = {
        **repaired_revision["actions"][1],
        "code": "def main(inputs):\n    import subprocess\n    return 'generated summary'",
    }
    llm = QueueLLM(
        _memory_compliance_payload(
            "repair_required",
            invalid_revision,
            memory_ids=["mem_git_guard"],
            confidence=0.92,
        ),
        {
            "decision": "repair_plan",
            **_repair_reasoning_fields(),
            "corrected_plan": repaired_revision,
            "retry_rationale": "Fix the structural Python contract while preserving the memory guard.",
            "expected_change": "The python_action starts with def main(inputs).",
            "confidence": 0.9,
        },
    )
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
        ),
        result_store=InMemoryResultStore(),
    )
    request = UserRequest(
        raw_prompt='review git changes, stage, commit with message "generated", and push',
        session_context={"agent_memory_directives": [directive]},
    )

    repaired_plan, errors = pipeline._review_memory_compliance(request, original_plan)

    assert errors == []
    assert llm.schemas == ["MemoryComplianceReview", "OperatorRepair"]
    assert "memory_compliance_revision_validation_failed" in llm.prompts[1]
    assert "python_action_contract_shape" in llm.prompts[1]
    assert "git rev-parse --is-inside-work-tree" in str(repaired_plan.actions[0].command)
    assert str(repaired_plan.actions[1].code).startswith("def main(inputs):")


