def test_final_formatter_uses_answer_judge_feedback_for_status_only_answer(
    tmp_path: Path,
) -> None:
    llm = QueueLLM(
        {
            "code": "def transform(inputs):\n    return 'Execution completed.'",
            "declared_output_shape": "markdown",
            "reason": "Too vague.",
            "confidence": 0.8,
        },
        {
            "verdict": "revise_formatter",
            "answers_user_request": False,
            "uses_available_outputs": False,
            "issues": ["The answer omits the listed environments."],
            "feedback_for_formatter": "Use records[0].stdout to render the conda environment names.",
            "reason": "The source preview contains env rows but the answer does not.",
            "confidence": 0.93,
        },
        {
            "code": (
                "def transform(inputs):\n"
                "    envs = [line.strip() for line in inputs['records'][0]['stdout'].splitlines() if line.strip()]\n"
                "    return 'Environments: ' + ', '.join(envs)"
            ),
            "declared_output_shape": "markdown",
            "reason": "Render the source rows.",
            "confidence": 0.96,
        },
        {
            "verdict": "accept",
            "answers_user_request": True,
            "uses_available_outputs": True,
            "issues": [],
            "feedback_for_formatter": "",
            "reason": "The answer includes the available environment rows.",
            "confidence": 0.97,
        },
    )

    result = run_llm_final_formatter(
        user_request=UserRequest(raw_prompt="summarize conda environments"),
        sources=[
            FormatterSource(
                source_id="action_1",
                label="List conda envs",
                kind="shell_command",
                status="success",
                command="conda env list",
                declared_output_shape="text",
                stdout="base\nwan\n",
                exit_code=0,
            )
        ],
        llm_client=llm,
        validator=OperatorPlanValidator(RuntimeConfig(workspace_root=str(tmp_path))),
        python_executor=PythonTransformExecutor(),
        include_source_previews=True,
        answer_judge_enabled=True,
    )

    assert result is not None
    assert result.content == "Environments: base, wan"
    assert llm.schemas == [
        "OperatorFinalFormatter",
        "OperatorAnswerJudge",
        "OperatorFinalFormatter",
        "OperatorAnswerJudge",
    ]
    assert "base" in llm.prompts[1]
    assert "Use records[0].stdout" in llm.prompts[2]


