def test_python_transform_output_streams_to_command_output(tmp_path: Path) -> None:
    plan = _plan_payload()
    plan["actions"][0] = {
        "action_id": "action_1",
        "task_id": "task_1",
        "kind": "python_transform",
        "code": "def transform(inputs):\n    return {'count': 2}",
        "cwd": ".",
        "inputs": {},
        "input_bindings": [],
        "declared_output_shape": "json",
        "risk": "low",
        "timeout_seconds": 5,
        "reason": "Calculate count.",
        "depends_on": [],
    }
    sink = InMemoryEventSink()
    observability = build_observability_context(
        "req-python-stream",
        {
            "observability": {
                "enabled": True,
                "debug": True,
                "sinks": [sink],
            }
        },
    )
    pipeline = _pipeline(tmp_path, QueueLLM(plan, _formatter_payload()))
    request = UserRequest(raw_prompt="calculate count", session_context={"target_ui": "agent_ui"})
    accepted, _ = pipeline.propose_and_validate(request)

    result = pipeline.execute_approved(request, accepted, {"confirmation": True}, observability)

    assert result.status == "success"
    events = sink.events
    command_events = [event for event in events if event.event_type.startswith("execution.command.")]
    assert [event.event_type for event in command_events] == [
        "execution.command.started",
        "execution.command.stdout",
        "execution.command.completed",
    ]
    assert command_events[0].details["execution_snippet_language"] == "python"
    assert command_events[0].details["execution_snippet_label"] == "Python transform"
    assert "def transform(inputs):" in command_events[0].details["execution_snippet"]
    assert "def transform(inputs):" in command_events[0].details["command"]
    assert "runs the Python transform code shown below" in command_events[0].details["operation_description"]
    assert '"count": 2' in command_events[1].details["text"]
    assert "def transform(inputs):" in command_events[1].details["command"]
    assert command_events[1].details["terminal_dispatch"] is False
    assert result.execution_records[0].metadata["execution_snippet_language"] == "python"
    assert "return {'count': 2}" in result.execution_records[0].metadata["execution_snippet"]
    assert "runs the Python transform code shown below" in result.execution_records[0].metadata["operation_description"]


