def test_operator_injects_shell_stdout_into_python_transform(tmp_path: Path) -> None:
    plan = _plan_payload(command="df -k / | awk 'NR==2 {print $4}'")
    plan["tasks"].append(
        {
            "task_id": "task_2",
            "goal": "Convert kilobytes to gigabytes",
            "semantic_verb": "transform",
            "object_type": "text",
            "dependencies": ["task_1"],
            "reason": "The shell output needs unit conversion.",
        }
    )
    plan["actions"].append(
        {
            "action_id": "action_2",
            "task_id": "task_2",
            "kind": "python_transform",
            "code": (
                "def transform(inputs):\n"
                "    kb_free = int(str(inputs['disk_free_kb']).strip())\n"
                "    gb_free = round(kb_free / (1024 * 1024), 2)\n"
                "    return f'{gb_free} GB'"
            ),
            "cwd": ".",
            "inputs": {},
            "input_bindings": [
                {
                    "input_name": "disk_free_kb",
                    "source_action_id": "action_1",
                    "source_field": "stdout",
                }
            ],
            "declared_output_shape": "text",
            "risk": "low",
            "timeout_seconds": 5,
            "reason": "Convert stdout from action_1.",
            "depends_on": [],
        }
    )
    gateway = NumericOperatorGateway()
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(
            plan,
            {
                "code": (
                    "def transform(inputs):\n"
                    "    kb_free = int(str(inputs['disk_free_kb']).strip())\n"
                    "    gb_free = round(kb_free / (1024 * 1024), 2)\n"
                    "    return f'{gb_free} GB'"
                ),
                "declared_output_shape": "text",
                "allow_zero_result": False,
                "reason": "Convert stdout from action_1 after seeing the real input.",
                "confidence": 0.95,
            },
        ),
        gateway,
    )
    accepted, _ = pipeline.propose_and_validate(UserRequest(raw_prompt="show disk free in GB"))
    pending = pipeline.require_confirmation(UserRequest(raw_prompt="show disk free in GB"), accepted)

    result = pipeline.execute_approved(
        UserRequest(raw_prompt="show disk free in GB"),
        accepted,
        {"confirmation": True},
    )

    assert "### Output Flow" in pending.final_response
    assert (
        "- `Run a command` `stdout` -> "
        "`Convert kilobytes to gigabytes` input `disk_free_kb`"
    ) in pending.final_response
    assert result.status == "success"
