def test_operator_protects_literal_shell_input_from_output_binding(
    tmp_path: Path,
) -> None:
    payload = _plan_payload(command="printf true", cwd=str(tmp_path))
    payload["tasks"][0]["goal"] = "Probe a runtime value"
    payload["actions"][0]["reason"] = "Probe a value that must not replace user payloads."
    payload["tasks"].append(
        {
            "task_id": "task_2",
            "goal": "Use the protected literal message",
            "semantic_verb": "execute",
            "object_type": "shell.command",
            "dependencies": ["task_1"],
            "reason": "The downstream command consumes the user-provided message.",
        }
    )
    payload["actions"].append(
        {
            "action_id": "action_2",
            "task_id": "task_2",
            "kind": "shell_command",
            "command": 'printf "%s\\n" "$OF_INPUT_MESSAGE"',
            "cwd": str(tmp_path),
            "inputs": {},
            "input_bindings": [
                {
                    "input_name": "message",
                    "source_action_id": "action_1",
                    "source_field": "stdout",
                    "required": True,
                    "fallback_value": None,
                }
            ],
            "declared_output_shape": "text",
            "risk": "low",
            "timeout_seconds": 5,
            "reason": "Use the literal message through a shell input.",
            "depends_on": ["action_1"],
        }
    )
    plan = OperatorPlan.model_validate(payload)
    request = UserRequest(
        raw_prompt="print [provided message payload]",
        session_context={
            OPERATOR_LITERAL_PAYLOADS_CONTEXT_KEY: [
                {
                    "payload_id": "literal_payload_1",
                    "kind": "content_payload",
                    "label": "message",
                    "input_name": "message",
                    "placeholder": "[provided message payload]",
                    "value": "hello protected",
                    "value_length": len("hello protected"),
                    "preview": "hello protected",
                }
            ]
        },
    )
    gateway = FakeOperatorGateway()
    pipeline = _pipeline(tmp_path, QueueLLM(), gateway)

    errors = pipeline._validate_plan(request, plan)
    result = pipeline.execute_approved(request, plan, {"confirmation": True})

    assert errors == []
    assert plan.actions[1].inputs["message"] == "hello protected"
    assert plan.actions[1].input_bindings == []
    assert result.status == "success"
    assert gateway.raw_calls[1]["execution_context"]["shell_env"]["OF_INPUT_MESSAGE"] == (
        "hello protected"
    )


