def test_operator_action_rejects_invalid_llm_text_payloads() -> None:
    payload = _llm_text_plan_payload()["actions"][1]

    with pytest.raises(ValueError, match="llm_prompt"):
        OperatorAction.model_validate({**payload, "llm_prompt": ""})

    with pytest.raises(ValueError, match="must not include command"):
        OperatorAction.model_validate({**payload, "command": "printf nope"})

    with pytest.raises(ValueError, match="must not include code"):
        OperatorAction.model_validate({**payload, "code": "def main(inputs): pass"})

    with pytest.raises(ValueError, match="must not include shell stdin"):
        OperatorAction.model_validate(
            {**payload, "stdin_mode": "literal", "stdin_text": "payload"}
        )


