def test_operator_confirm_bound_pauses_after_upstream_output(tmp_path: Path) -> None:
    plan = OperatorPlan.model_validate(_bound_shell_plan_payload())
    gateway = BoundShellValueGateway(first_stdout="def456\n")
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(),
        gateway,
        config_overrides={"shell_input_bindings_mode": "confirm_bound"},
    )

    pending = pipeline.execute_approved(
        UserRequest(raw_prompt="reuse commit hash"),
        plan,
        {"confirmation": True},
    )

    assert pending.status == "confirmation_required"
    assert pending.metadata["shell_input_bindings_confirmation_pending"] is True
    assert pending.metadata["shell_input_bindings_action_id"] == "action_2"
    assert pending.execution_records[0].stdout == "def456\n"
    assert len(gateway.raw_calls) == 1

    resumed = pipeline.execute_approved(
        UserRequest(raw_prompt="reuse commit hash"),
        plan,
        {
            "confirmation": True,
            "operator_seed_records": [
                record.model_dump(mode="json") for record in pending.execution_records
            ],
            "shell_input_bindings_confirmed_action_ids": ["action_2"],
        },
    )

    assert resumed.status == "success"
    assert len(gateway.raw_calls) == 2
    assert gateway.raw_calls[1]["execution_context"]["shell_env"] == {
        "OF_INPUT_COMMIT_HASH": "def456"
    }


