def test_operator_does_not_skip_current_action_for_colliding_streaming_seed(
    tmp_path: Path,
) -> None:
    prior_record = OperatorExecutionRecord(
        action_id="action_1",
        task_id="task_previous",
        kind="shell_command",
        status="success",
        stdout="previous step output\n",
        stderr="",
        exit_code=0,
        output=None,
        error=None,
        metadata={
            "streaming_step_id": "stream-step-1-task-previous",
            "streaming_task_id": "task_previous",
            "streaming_step_index": 0,
        },
    )
    plan = OperatorPlan.model_validate(_plan_payload(command="printf current"))
    gateway = FakeOperatorGateway()
    pipeline = _pipeline(tmp_path, QueueLLM(), gateway)
    seed_payload = [prior_record.model_dump(mode="json")]

    result = pipeline.execute_approved(
        UserRequest(raw_prompt="run current streaming step"),
        plan,
        {
            "confirmation": True,
            "operator_seed_records": seed_payload,
            "operator_execution_step_id": "stream-step-2-task-1",
            "operator_streaming_step_id": "stream-step-2-task-1",
            "operator_streaming_current_task": {"task_id": "task_1"},
            "operator_streaming_current_index": 1,
        },
    )

    assert result.status == "success"
    assert [call["command"] for call in gateway.raw_calls] == ["printf current"]
    assert result.execution_records[-1].action_id == "action_1"
    assert result.execution_records[-1].task_id == "task_1"
    assert result.execution_records[-1].metadata["streaming_step_id"] == "stream-step-2-task-1"
    assert result.execution_records[-1].metadata["operator_execution_step_id"] == (
        "stream-step-2-task-1"
    )


def test_execution_repair_keeps_referenced_external_streaming_seed(
    tmp_path: Path,
) -> None:
    prior_record = OperatorExecutionRecord(
        action_id="action_1",
        task_id="task_1",
        kind="shell_command",
        status="success",
        stdout="upstream rows\n",
        stderr="",
        exit_code=0,
        output=None,
        error=None,
        metadata={
            "streaming_step_id": "stream-step-1-task-1",
            "streaming_task_id": "task_1",
            "streaming_step_index": 0,
        },
    )
    failed_record = OperatorExecutionRecord(
        action_id="action_2",
        task_id="task_2",
        kind="python_action",
        status="error",
        stdout="",
        stderr="",
        exit_code=1,
        output=None,
        error="bad parser",
        metadata={},
    )
    original_plan = OperatorPlan.model_validate(
        {
            "summary": "Calculate current step.",
            "tasks": [
                {
                    "task_id": "task_2",
                    "goal": "Calculate total",
                    "semantic_verb": "calculate",
                    "object_type": "data",
                    "dependencies": ["task_1"],
                    "reason": "",
                }
            ],
            "actions": [
                {
                    "action_id": "action_2",
                    "task_id": "task_2",
                    "kind": "python_action",
                    "code": "def main(inputs):\n    raise ValueError('bad parser')",
                    "cwd": ".",
                    "inputs": {},
                    "input_bindings": [
                        {
                            "input_name": "rows",
                            "source_action_id": "action_1",
                            "source_field": "stdout",
                            "required": True,
                            "fallback_value": None,
                        }
                    ],
                    "declared_output_shape": "text",
                    "risk": "low",
                    "reason": "Parse rows.",
                    "depends_on": [],
                }
            ],
            "dependencies": [],
            "expected_outputs": ["total"],
            "assumptions": [],
        }
    )
    repaired_plan = original_plan.model_copy(
        update={
            "actions": [
                original_plan.actions[0].model_copy(
                    update={"code": "def main(inputs):\n    return inputs['rows']"}
                )
            ]
        }
    )
    pipeline = _pipeline(tmp_path, QueueLLM())

    seed_records = pipeline._repair_seed_records(
        original_plan,
        repaired_plan,
        [prior_record, failed_record],
    )

    assert [record.action_id for record in seed_records] == ["action_1"]


def test_streaming_state_keeps_current_record_when_seed_action_id_collides() -> None:
    prior_record = OperatorExecutionRecord(
        action_id="action_1",
        task_id="task_previous",
        kind="shell_command",
        status="success",
        stdout="previous step output\n",
        stderr="",
        exit_code=0,
        output=None,
        error=None,
        metadata={
            "streaming_step_id": "stream-step-1-task-previous",
            "streaming_task_id": "task_previous",
            "streaming_step_index": 0,
        },
    )
    current_record = OperatorExecutionRecord(
        action_id="action_1",
        task_id="task_1",
        kind="shell_command",
        status="success",
        stdout="current step output\n",
        stderr="",
        exit_code=0,
        output=None,
        error=None,
        metadata={},
    )
    state = {
        "current_index": 1,
        "completed_task_ids": ["task_previous"],
        "tasks": [
            {
                "task_id": "task_previous",
                "description": "Previous step",
                "streaming_step_id": "stream-step-1-task-previous",
            },
            {
                "task_id": "task_1",
                "description": "Current step",
                "streaming_step_id": "stream-step-2-task-1",
            },
        ],
        "prior_results": [
            {
                "task_id": "task_previous",
                "description": "Previous step",
                "status": "success",
                "final_response": "done",
                "records": [prior_record.model_dump(mode="json")],
            }
        ],
    }
    result = OperatorPipelineResult(
        status="success",
        final_response="done",
        execution_records=[prior_record, current_record],
        metadata={},
    )

    updated = AgentRuntime._streaming_state_after_step(
        state,
        task={
            "task_id": "task_1",
            "description": "Current step",
            "streaming_step_id": "stream-step-2-task-1",
        },
        result=result,
    )

    new_records = updated["prior_results"][-1]["records"]
    assert [record["stdout"] for record in new_records] == ["current step output\n"]
    assert new_records[0]["metadata"]["streaming_step_id"] == "stream-step-2-task-1"
    assert new_records[0]["metadata"]["streaming_task_id"] == "task_1"


