def test_operator_rejects_unresolved_shell_placeholder_and_repairs(tmp_path: Path) -> None:
    invalid = _plan_payload(command="git log -1 --oneline {branch_name}")
    repaired = _plan_payload(
        command=(
            "branch_name=$(git branch -a | sed 's/^..//' | grep -i distil | head -n 1); "
            "git log -1 --oneline \"$branch_name\""
        )
    )
    llm = QueueLLM(
        invalid,
        {
            **_repair_reasoning_fields(),
            "corrected_plan": repaired,
            "retry_rationale": "Replace the unresolved placeholder with a local shell assignment.",
            "expected_change": "The command is concrete at approval time.",
            "confidence": 0.9,
        },
    )
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            gateway_timeout_seconds=30,
            llm_operator_max_deferred_code_repair_attempts=0,
        ),
        result_store=InMemoryResultStore(),
    )

    accepted, errors = pipeline.propose_and_validate(
        UserRequest(raw_prompt="show latest change on distil branch")
    )

    assert errors == []
    assert accepted.actions[0].command == repaired["actions"][0]["command"]
    assert len(llm.prompts) == 2
    repair_prompt = llm.prompts[1]
    assert "unresolved_shell_placeholder" in repair_prompt
    assert "Rejected plan:" in repair_prompt
    assert "git log -1 --oneline {branch_name}" in repair_prompt
    assert "python_action/python_transform actions with input_bindings" in repair_prompt
    assert "Shell input bindings mode: allow" in repair_prompt
    assert "only OF_INPUT_* variables backed by declared input_bindings are allowed" in repair_prompt
    assert "runtime placeholders like {{container_name}} are not allowed" in repair_prompt
    assert "Bad: docker inspect {{container_name}}" in repair_prompt
    assert "Operator Python is trusted local execution like shell" in repair_prompt
    assert "Every action.task_id must exactly match" in llm.prompts[0]
    assert "use python_action" in llm.prompts[0]
    assert "handle exceptions inside each iteration" in llm.prompts[0]
    assert "never return 0, an empty table, or a success string" in llm.prompts[0]
    assert "track how many values were actually parsed" in llm.prompts[0]
    assert "An action cannot bind inputs from itself" in llm.prompts[0]
    assert "code must start with def transform(inputs):" in llm.prompts[0]
    assert "Put imports inside the Python function body" in llm.prompts[0]
    assert "Prefer direct inputs['stdout'] access for required bound inputs" in llm.prompts[0]
    assert "Captured Python should use inputs or subprocess output rather than interactive stdin" in llm.prompts[0]
    assert "prefer machine-readable CLI output" in llm.prompts[0]
    assert "destructive commands, select targets by stable ids" in llm.prompts[0]
    assert "exit 0 for both outcomes" in llm.prompts[0]
    assert "no-match status" in llm.prompts[0]
    assert "case-insensitive fixed substring matching" in llm.prompts[0]
    assert "Verify the exact user-requested postcondition" in llm.prompts[0]
    assert "Prefer machine-readable state commands" in llm.prompts[0]
    assert "Do not grep human-oriented command prose" in llm.prompts[1]


def test_operator_auto_rephrase_retries_after_validation_exhausted(tmp_path: Path) -> None:
    invalid = _plan_payload(command="git log -1 --oneline {branch_name}")
    accepted_payload = _plan_payload(command="git log -1 --oneline HEAD")
    llm = QueueLLM(
        invalid,
        {
            "rephrased_prompt": "Show the latest commit on the current branch using a concrete git command.",
            "reason": "Avoid placeholder-looking braces in the shell command.",
            "confidence": 0.92,
        },
        accepted_payload,
    )
    pipeline = _pipeline(
        tmp_path,
        llm,
        config_overrides={
            "llm_operator_max_validation_repair_attempts": 0,
            "llm_operator_self_brief_mode": "off",
        },
    )
    trace = PlanningTrace(request_id="req-auto-rephrase", raw_prompt="show latest change on branch")
    request = UserRequest(
        raw_prompt="show latest change on branch",
        safety_context={"planning_trace": trace},
    )

    accepted, errors = pipeline.propose_and_validate(request)

    assert errors == []
    assert accepted.actions[0].command == "git log -1 --oneline HEAD"
    assert llm.schemas.count("OperatorPlan") == 2
    assert "OperatorRephraseRetryProposal" in llm.schemas
    retry_prompt = llm.prompts[llm.schemas.index("OperatorRephraseRetryProposal")]
    assert "unresolved_shell_placeholder" in retry_prompt
    assert "{branch_name}" in retry_prompt
    assert trace.metadata["operator_auto_rephrase_retry_status"] == "succeeded"
    assert trace.metadata["operator_auto_rephrase_retries"][0]["original_prompt"] == (
        "show latest change on branch"
    )
    assert trace.metadata["operator_auto_rephrase_retries"][0]["rephrased_prompt"] == (
        "Show the latest commit on the current branch using a concrete git command."
    )


def test_operator_auto_rephrase_can_be_disabled(tmp_path: Path) -> None:
    llm = QueueLLM(_plan_payload(command="git log -1 --oneline {branch_name}"))
    pipeline = _pipeline(
        tmp_path,
        llm,
        config_overrides={
            "llm_operator_max_validation_repair_attempts": 0,
            "llm_operator_self_brief_mode": "off",
            "operator_auto_rephrase_retry_enabled": False,
        },
    )
    trace = PlanningTrace(request_id="req-auto-rephrase-disabled", raw_prompt="show latest change on branch")
