def test_operator_validation_policy_memory_usage_is_emitted(tmp_path: Path) -> None:
    command = "\n".join(
        [
            "cat > main.cpp <<'CPP'",
            "#include <iostream>",
            "int main() { std::cout << \"hi\\\\n\"; return 0; }",
            "CPP",
        ]
    )
    store = AgentMemoryStore(tmp_path / "agent-memory.db")
    memory = store.create_entry(
        MemoryEntryCreate(
            instruction="Allow <iostream> when it is literal C++ source payload in a quoted heredoc.",
            summary="C++ include literal validation policy.",
            memory_kind="validation_policy",
            task_type="shell",
            tool_type="shell_command",
            intent_type="execute",
            validator_error_type="unresolved_shell_placeholder",
            safe_examples=["#include <iostream> inside cat > main.cpp <<'CPP'"],
            blocked_examples=["echo '<calculated_value>'"],
            tags=["literal_payload", "iostream"],
        )
    )
    sink = InMemoryEventSink()
    observability = build_observability_context(
        "req-validation-memory",
        {
            "observability": {
                "enabled": True,
                "debug": True,
                "sinks": [sink],
            }
        },
    )
    llm = QueueLLM(_plan_payload(command=command), _validation_adjudication_payload())
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            gateway_timeout_seconds=30,
        ),
        result_store=InMemoryResultStore(),
        memory_store=store,
    )

    accepted, errors = pipeline.propose_and_validate(
        UserRequest(raw_prompt="create a C++ file with #include <iostream>"),
        observability,
    )

    assert errors == []
    assert accepted.actions[0].command == command
    adjudication_events = [
        event for event in sink.events if event.event_type == "operator.validation.adjudicated"
    ]
    assert adjudication_events
    details = adjudication_events[-1].details
    assert details["memory_kind"] == "validation_policy"
    assert details["memory_count"] == 1
    assert details["memory_ids"] == [memory.memory_id]
    assert details["policy_memory_ids"] == [memory.memory_id]
    assert details["memory_use_counts"][memory.memory_id] == 1


