    docker_errors = validator.validate(
        OperatorPlan.model_validate(_plan_payload(command="docker inspect {{container_name}}"))
    )

    assert any(error["error"] == "unresolved_shell_placeholder" for error in echo_errors)
    assert any(error["error"] == "unresolved_shell_placeholder" for error in branch_errors)
    assert any(error["error"] == "unresolved_shell_placeholder" for error in docker_errors)
    assert not any(error.get("context_sensitive") for error in echo_errors + branch_errors + docker_errors)


