def test_operator_self_brief_prompt_compacts_streaming_context() -> None:
    request = UserRequest(
        raw_prompt="Original request: find compose files\nStreaming step 2 of 2: start services",
        session_context={
            "operator_streaming_current_task": {
                "task_id": "task-2",
                "description": "Start Docker Compose services using docker compose up for each found file",
                "semantic_verb": "execute",
            },
            "operator_streaming_prior_results": {
                "completed_tasks": [
                    {
                        "task_id": "task-1",
                        "description": "Search for docker-compose.yaml or yml files",
                        "status": "success",
                        "records": [
                            {
                                "action_id": "action-1",
                                "task_id": "task-1",
                                "kind": "shell_command",
                                "status": "success",
                                "exit_code": 0,
                                "stdout": "./webui/docker-compose.yml\n",
                                "metadata": {
                                    "cwd": "/home/vinith/models",
                                    "gateway_url": "http://127.0.0.1:8787",
                                    "terminal_dispatch": True,
                                },
                            }
                        ],
                    }
                ]
            },
            "operator_intent_block": {
                "mode": "decomposition_streaming_step",
                "global_constraints": {
                    "streaming_original_prompt": "find compose files then start them",
                    "streaming_prior_results": [{"records": [{"stdout": "./webui/docker-compose.yml"}]}],
                },
                "tasks": [{"task_id": "task-2"}],
            },
        },
    )

    prompt = build_operator_self_brief_prompt(request)

    assert "Streaming scope: prepare this self-brief only for the current decomposed task." in prompt
    assert "success_postcondition must describe what observable state or answer proves the current streaming step is complete." in prompt
    assert "recommended_strategy should be general and executable for the current streaming step" in prompt
    assert "original user request is background context" in prompt
    assert "When consuming prior relative path output, resolve it against the producing record's cwd" in prompt
    assert "./webui/docker-compose.yml" in prompt
    assert "/home/vinith/models" in prompt
    assert "gateway_url" not in prompt
    assert "terminal_dispatch" not in prompt
    assert "streaming_prior_results" not in prompt
    assert "OperatorSelfBrief schema" not in prompt


