def test_operator_clarification_mode_auto_resolves_typed_assumption(tmp_path: Path) -> None:
    llm = QueueLLM(
        {
            "decision": "ask_user",
            "clarification_request": {
                "question": "Which output format should I use?",
                "reason": "The output format was not selected explicitly.",
                "missing_information": "Output format",
                "options": [
                    {"option_id": "json", "label": "JSON", "description": "Return JSON."},
                    {
                        "option_id": "markdown",
                        "label": "Markdown",
                        "description": "Return Markdown.",
                    },
                ],
                "allow_freeform": True,
                "confidence": 0.82,
            },
            "reason": "The output format may affect the plan.",
            "confidence": 0.82,
        },
        {
            "decision": "continue_with_assumption",
            "mode": "balanced",
            "confidence": 0.94,
            "selected_entities": [
                {
                    "entity_type": "option",
                    "name": "JSON",
                    "value": "json",
                    "source": "user_prompt",
                    "confidence": 0.94,
                }
            ],
            "assumptions": ["Use JSON because the prompt asks for json output."],
            "execution_directives": ["Treat JSON as the selected output format."],
            "user_question": "",
            "risk_flags": [],
            "reason": "The prompt explicitly names json, so the option is a high-confidence match.",
        },
    )
    pipeline = _pipeline(tmp_path, llm)
    request = UserRequest(
        raw_prompt="summarize the report as json",
        session_context={"agent_clarification_mode": "balanced"},
    )

    decision = pipeline.complete_clarification_decision(request)

    assert decision.decision == "continue"
    assert decision.clarification_request is None
    assert llm.schemas == ["OperatorClarificationDecision", "AgentClarificationResolution"]
    assert request.session_context["agent_clarification_assumptions"] == [
        "Use JSON because the prompt asks for json output."
    ]
    assert request.session_context["agent_clarification_selected_entities"][0]["value"] == "json"
    assert request.session_context["agent_clarification_execution_directives"] == [
        "Treat JSON as the selected output format."
    ]


