def test_operator_validation_blocks_broad_find_wildcard_scope_for_named_dirs(tmp_path: Path) -> None:
    (tmp_path / "src").mkdir()
    (tmp_path / "tests").mkdir()
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(_plan_payload()),
    )
    plan = OperatorPlan.model_validate(
        _plan_payload(
            command=(
                'find "$PWD" -type f -name "*.py" -path "*/src/*" '
                '-o -name "*.py" -path "*/tests/*" | wc -l'
            ),
            cwd=str(tmp_path),
        )
    )

    errors = pipeline._validate_plan(
        UserRequest(raw_prompt="count Python files under src and tests"),
        plan,
    )

    error_names = {str(error.get("error") or "") for error in errors}
    assert "find_broad_root_wildcard_scope" in error_names
    assert "find_ungrouped_or_path_scope" in error_names
    assert "exact search roots" in " ".join(str(error.get("repair_hint") or "") for error in errors)


