def _canonical_db_parameter_request(tmp_path: Path) -> UserRequest:
    env = {
        "host": "OF_PARAM_CANONICA_V1_HOST",
        "port": "OF_PARAM_CANONICA_V1_PORT",
        "dbname": "OF_PARAM_CANONICA_V1_DBNAME",
        "user": "OF_PARAM_CANONICA_V1_USER",
        "password": "OF_PARAM_CANONICA_V1_PASSWORD",
    }
    parameter = {
        "key": "canonical_v1",
        "normalized_key": "canonica_v1",
        "exact": True,
        "env_names": list(env.values()),
        "database_profile": {
            "profile_type": "database_connection",
            "engine": "postgres",
            "identity": {
                "name": "canonical_v1",
                "database": "CANONICAL_v1",
            },
            "env": env,
        },
    }
    return UserRequest(
        raw_prompt="list schemas in the CANONICAL_v1 database",
        session_context={
            "workspace_root": str(tmp_path),
            "agent_parameter_store_matches": [parameter],
            "agent_parameter_shell_env_names": list(env.values()),
        },
    )


