def test_operator_zero_like_transform_output_from_nonempty_input_repairs(
    tmp_path: Path,
) -> None:
    plan = _plan_payload(command="docker images --format '{{.Size}}'")
    plan["tasks"].append(
        {
            "task_id": "task_2",
            "goal": "Calculate total image size",
            "semantic_verb": "calculate",
            "object_type": "docker.image",
            "dependencies": ["task_1"],
            "reason": "Aggregate sizes.",
        }
    )
    plan["actions"].append(
        {
            "action_id": "action_2",
            "task_id": "task_2",
            "kind": "python_transform",
            "code": "def transform(inputs):\n    return 'Total Docker image size: 0.00 GB'",
            "cwd": ".",
            "inputs": {},
            "input_bindings": [
                {
                    "input_name": "stdout",
                    "source_action_id": "action_1",
                    "source_field": "stdout",
                    "required": True,
                    "fallback_value": None,
                }
            ],
            "declared_output_shape": "text",
            "risk": "low",
            "timeout_seconds": 5,
            "reason": "Parse and sum Docker image sizes.",
            "depends_on": ["action_1"],
        }
    )
    repaired = _plan_payload(command="printf repaired-total")
    llm = QueueLLM(
        plan,
        {
            "code": "def transform(inputs):\n    return 'Total Docker image size: 0.00 GB'",
            "declared_output_shape": "text",
            "allow_zero_result": False,
            "reason": "Preserve the intentionally broken aggregate for repair testing.",
            "confidence": 0.9,
        },
        {
            **_repair_reasoning_fields(),
            "corrected_plan": repaired,
            "retry_rationale": "The transform returned zero from non-empty input.",
            "expected_change": "Use a corrected parser.",
            "confidence": 0.9,
        },
    )
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            gateway_timeout_seconds=30,
            llm_operator_max_deferred_code_repair_attempts=0,
        ),
        result_store=InMemoryResultStore(),
    )
    accepted, errors = pipeline.propose_and_validate(
        UserRequest(raw_prompt="calculate docker image sizes")
    )

    result = pipeline.execute_approved(
        UserRequest(raw_prompt="calculate docker image sizes"),
        accepted,
        {"confirmation": True},
    )

    assert errors == []
    assert result.status == "success"
    assert result.execution_records[1].status == "error"
    assert "zero-like result" in str(result.execution_records[1].error)
    assert result.execution_records[-1].stdout == "hello"
    repair_prompt = "\n".join(llm.prompts)
    assert "Live execution failure packet" in repair_prompt
    assert "zero-like result" in repair_prompt
    assert "allow_zero_result" in repair_prompt


