    assert "bound_inputs_preview" in repair_prompt
    assert "For Python subprocess failures" in repair_prompt
    assert "Total space consumed by Docker images: 0.00 MB" in repair_prompt
    assert "zero-like result" in repair_prompt
    assert "Do not defer repaired Python code" in repair_prompt


