    runtime_contract = {"stdout": {"runtime_type": "string", "sample_value": "postgres:15 633MB\n"}}

    assert (
        generated_python_regex_literal_errors(
            code,
            input_packet=preview,
            runtime_contract=runtime_contract,
        )
        == []
    )


