def test_generated_python_proof_rejects_bad_decimal_parser_against_bound_input() -> None:
    action = _generated_python_size_action()
    bad_code = (
        "def main(inputs):\n"
        "    import re\n"
        "    size = inputs['stdout'].strip().split('\\t')[-1]\n"
        "    match = re.match(r'(\\d+(?:\\\\.\\d+)?)\\s*([A-Za-z]+)', size)\n"
        "    if not match:\n"
        "        raise ValueError(f'Invalid size format: {size}')\n"
        "    return {'parsed': match.group(0)}\n"
    )
    rows = "abc\trepo\ttag\t2.43GB\n"
    input_packet = {"stdout": {"type": "string", "preview": rows}}
    runtime_contract = {"stdout": {"runtime_type": "string", "sample_value": rows}}

    proof = generated_python_proof_result(
        action,
        bad_code,
        action_inputs={"stdout": rows},
        input_packet=input_packet,
        runtime_contract=runtime_contract,
    )

    assert proof.decision == "reject"
    assert proof.proof_mode == "pure_runtime_sample"
    assert proof.errors[0]["error"] == "generated_python_sample_execution_failed"
    assert "Invalid size format: 2.43GB" in proof.stderr_preview


def test_generated_python_proof_accepts_numeric_prefix_parser() -> None:
    action = _generated_python_size_action()
    good_code = (
        "def main(inputs):\n"
        "    total = 0.0\n"
        "    units = {'B': 1, 'KB': 1024, 'MB': 1024 ** 2, 'GB': 1024 ** 3}\n"
        "    for line in inputs['stdout'].splitlines():\n"
        "        token = line.split('\\t')[-1].strip()\n"
        "        split_at = 0\n"
        "        while split_at < len(token) and (token[split_at].isdigit() or token[split_at] == '.'):\n"
        "            split_at += 1\n"
        "        number = float(token[:split_at])\n"
        "        unit = token[split_at:].strip().upper()\n"
        "        total += number * units[unit]\n"
        "    return {'total_size_bytes': total, 'total_size_gb': round(total / (1024 ** 3), 2)}\n"
    )
    rows = "abc\trepo\ttag\t2.43GB\nbase\tubuntu\t24.04\t119MB\n"
    input_packet = {"stdout": {"type": "string", "preview": rows}}
    runtime_contract = {"stdout": {"runtime_type": "string", "sample_value": rows}}

    proof = generated_python_proof_result(
        action,
        good_code,
        action_inputs={"stdout": rows},
        input_packet=input_packet,
        runtime_contract=runtime_contract,
    )

    assert proof.decision == "accept"
    assert proof.proof_mode == "pure_runtime_sample"
    assert "total_size_gb" in proof.stdout_preview


