    code = (
        "def main(inputs):\n"
        "    with open('docker_size.txt', 'w') as handle:\n"
        "        handle.write(inputs['result'])\n"
        "    return 'saved'\n"
    )
    input_packet = {"result": {"type": "string", "preview": "{\"total\": 1}"}}
    runtime_contract = {"result": {"runtime_type": "string", "sample_value": "{\"total\": 1}"}}

    proof = generated_python_proof_result(
        action,
        code,
        action_inputs={"result": "{\"total\": 1}"},
        input_packet=input_packet,
        runtime_contract=runtime_contract,
    )

    assert proof.decision == "skip_execution"
    assert proof.errors[0]["error"] == "generated_python_runtime_sample_skipped"


