def test_standard_agent_execution_failure_repairs_with_live_context(tmp_path: Path) -> None:
    registry = build_default_registry()
    gateway = FailingThenSuccessOperatorGateway()
    store = InMemoryResultStore()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
        ),
        store,
        gateway_client=gateway,  # type: ignore[arg-type]
    )
    repaired = {
        **_repair_reasoning_fields(),
        "corrected_plan": _plan_payload(command="printf repaired"),
        "retry_rationale": "The first command failed with missing file.",
        "expected_change": "Use a command that succeeds.",
        "confidence": 0.9,
    }
    llm = QueueLLM(
        _tool_classification_payload(["operator"]),
        _plan_payload(command="cat missing.txt"),
        repaired,
        _formatter_payload("Recovered from the execution failure."),
    )
    runtime = AgentRuntime(
        llm,
        registry,
        engine,
        OutputPipelineOrchestrator(),
    )

    result = runtime.handle_request(
        "read the file and recover if it fails",
        {"workspace_root": str(tmp_path), "workflow_execution_mode": "full_plan"},
    )

    assert result == "repaired"
    assert [call["command"] for call in gateway.raw_calls] == ["cat missing.txt", "printf repaired"]
    repair_prompt = next(prompt for prompt in llm.prompts if "failed Agent operator plan" in prompt)
    assert "failed Agent operator plan" in repair_prompt
    assert "Live execution failure packet" in repair_prompt
    assert "missing file" in repair_prompt
    assert runtime.last_planning_trace.metadata["agent_mode"] == "standard_operator"


def test_operator_failure_continuation_replays_from_failed_action_only(tmp_path: Path) -> None:
    class ContinuationGateway(FakeOperatorGateway):
        def execute_raw_command(
            self,
            *,
            command: str,
            cwd: str,
            execution_context: dict[str, Any] | None = None,
        ) -> dict[str, Any]:
            if command == "printf RECOVERED":
                raise AssertionError("completed action was replayed")
            return super().execute_raw_command(
                command=command,
                cwd=cwd,
                execution_context=execution_context,
            )

    plan = OperatorPlan.model_validate(
        {
            "summary": "Continue a failed run.",
            "tasks": [
                {
                    "task_id": "task_1",
                    "goal": "Produce reusable output",
                    "semantic_verb": "observe",
                    "object_type": "text",
                    "dependencies": [],
                    "reason": "The next step consumes this value.",
                },
                {
                    "task_id": "task_2",
                    "goal": "Consume reusable output",
                    "semantic_verb": "observe",
                    "object_type": "text",
                    "dependencies": ["task_1"],
                    "reason": "This failed and should be retried.",
                },
                {
                    "task_id": "task_3",
                    "goal": "Verify continuation",
                    "semantic_verb": "observe",
                    "object_type": "text",
                    "dependencies": ["task_2"],
                    "reason": "This should run after the failed step.",
                },
            ],
            "actions": [
                {
                    "action_id": "action_1",
                    "task_id": "task_1",
                    "kind": "shell_command",
                    "command": "printf RECOVERED",
                    "cwd": ".",
                    "inputs": {},
                    "input_bindings": [],
                    "declared_output_shape": "text",
                    "risk": "low",
                    "timeout_seconds": 5,
                    "reason": "Produce reusable output.",
                    "depends_on": [],
                },
                {
                    "action_id": "action_2",
                    "task_id": "task_2",
                    "kind": "shell_command",
                    "command": 'printf "%s" "$OF_INPUT_MESSAGE"',
                    "cwd": ".",
                    "inputs": {},
                    "input_bindings": [
                        {
                            "input_name": "message",
                            "source_action_id": "action_1",
                            "source_field": "stdout",
                            "required": True,
                            "fallback_value": None,
                        }
                    ],
                    "declared_output_shape": "text",
                    "risk": "low",
                    "timeout_seconds": 5,
                    "reason": "Consume the reusable output.",
                    "depends_on": ["action_1"],
                },
                {
                    "action_id": "action_3",
                    "task_id": "task_3",
                    "kind": "shell_command",
                    "command": "printf verified",
                    "cwd": ".",
                    "inputs": {},
                    "input_bindings": [],
                    "declared_output_shape": "text",
                    "risk": "low",
                    "timeout_seconds": 5,
                    "reason": "Verify continuation.",
                    "depends_on": ["action_2"],
                },
            ],
            "dependencies": [],
            "expected_outputs": ["verified"],
            "assumptions": [],
            "confidence": 0.95,
        }
    )
    records = [
        OperatorExecutionRecord(
            action_id="action_1",
            task_id="task_1",
            kind="shell_command",
            status="success",
            stdout="RECOVERED",
            stderr="",
            exit_code=0,
        ),
        OperatorExecutionRecord(
            action_id="action_2",
            task_id="task_2",
            kind="shell_command",
            status="error",
            stdout="",
            stderr="transient failure",
            exit_code=1,
            error="Command failed.",
        ),
    ]
    registry = build_default_registry()
    gateway = ContinuationGateway()
    runtime = AgentRuntime(
        QueueLLM(),
        registry,
        ExecutionEngine(
            registry,
            RuntimeConfig(
                workspace_root=str(tmp_path),
                allow_shell_execution=True,
                gateway_url="http://gateway",
            ),
            InMemoryResultStore(),
            gateway_client=gateway,  # type: ignore[arg-type]
        ),
        OutputPipelineOrchestrator(),
    )
    trace = PlanningTrace(request_id="req-continuation", raw_prompt="continue failed run")
    trace.metadata.update(
        {
            "agent_mode": "llm_operator",
            "operator_plan": plan.model_dump(mode="json"),
            "operator_execution_records": [record.model_dump(mode="json") for record in records],
        }
    )
    sink = InMemoryEventSink()

    result = runtime.continue_from_trace(
        trace,
        {
            "agent_mode": "llm_operator",
            "shell_input_bindings_mode": "allow",
            "observability": {"enabled": True, "sink": sink},
        },
    )

    assert "RECOVERED" in result
    assert "hello" in result
    assert [call["command"] for call in gateway.raw_calls] == [
        'printf "%s" "$OF_INPUT_MESSAGE"',
        "printf verified",
    ]
    assert gateway.raw_calls[0]["execution_context"]["shell_env"] == {
        "OF_INPUT_MESSAGE": "RECOVERED"
    }
    assert "OperatorFailureContinuationReview" not in runtime.llm_client.schemas
    event_types = [event.event_type for event in sink.events]
    assert "operator.continuation.seeded" in event_types
    assert "operator.continuation.reviewed" not in event_types


def test_operator_failure_continuation_resumes_streaming_step_with_failure_evidence(
    tmp_path: Path,
) -> None:
    retry_plan = _plan_payload("printf recovered", cwd=str(tmp_path))
    retry_plan["summary"] = "Retry the failed streaming step."
    retry_plan["tasks"][0].update(
        {
            "task_id": "task-2",
            "goal": "Extract branch commit times",
            "semantic_verb": "read",
            "object_type": "git.branch",
            "dependencies": [],
        }
    )
    retry_plan["actions"][0].update(
        {
            "action_id": "action-1",
            "task_id": "task-2",
            "reason": "Retry the current streaming step after inspecting the failed attempt.",
        }
    )
    prior_success = {
        "action_id": "action-1",
        "task_id": "task-1",
        "kind": "shell_command",
        "status": "success",
        "stdout": "main\nfeature\n",
        "stderr": "",
        "exit_code": 0,
        "output": None,
        "error": None,
        "metadata": {
            "streaming_task_id": "task-1",
            "streaming_step_id": "stream-step-1-task-1",
            "streaming_step_index": 0,
        },
    }
    failed_attempt = {
        "action_id": "action-1",
        "task_id": "task-2",
        "kind": "python_action",
        "status": "error",
        "stdout": "",
        "stderr": "fatal: failed to stat 'main\\nfeature': File name too long",
        "exit_code": 1,
        "output": None,
        "error": "The prior branch list was used as one branch name.",
        "metadata": {
            "streaming_task_id": "task-2",
            "streaming_step_id": "stream-step-2-task-2",
            "streaming_step_index": 1,
        },
    }
    streaming_state = {
        "original_prompt": "list branches then extract commit times for each branch",
        "agent_mode": "llm_operator",
        "tasks": [
            {
                "task_id": "task-1",
                "description": "List all git branches",
                "semantic_verb": "list",
                "object_type": "git.branch",
                "dependencies": [],
                "streaming_step_id": "stream-step-1-task-1",
            },
            {
                "task_id": "task-2",
                "description": "Extract commit times for each listed branch",
                "semantic_verb": "read",
                "object_type": "git.branch",
                "dependencies": ["task-1"],
                "streaming_step_id": "stream-step-2-task-2",
            },
        ],
        "current_index": 1,
        "completed_task_ids": ["task-1"],
        "prior_results": [
            {
                "task_id": "task-1",
                "description": "List all git branches",
                "status": "success",
                "final_response": "Branches listed.",
                "records": [prior_success],
            },
            {
                "task_id": "task-2",
                "description": "Extract commit times for each listed branch",
                "status": "error",
                "final_response": "The branch list was consumed as one value.",
                "records": [failed_attempt],
            },
        ],
    }
    trace = PlanningTrace(
        request_id="req-streaming-continuation",
        raw_prompt=streaming_state["original_prompt"],
        metadata={
            "agent_mode": "llm_operator",
            "workflow_execution_mode": "streaming",
            "operator_streaming_state": streaming_state,
            "operator_plan": retry_plan,
            "operator_execution_records": [prior_success, failed_attempt],
        },
    )
    llm = QueueLLM(retry_plan)
    gateway = FixedShellResultGateway(stdout="recovered\n", stderr="", exit_code=0)
    registry = build_default_registry()
    runtime = AgentRuntime(
        llm,
        registry,
        ExecutionEngine(
            registry,
            RuntimeConfig(
                workspace_root=str(tmp_path),
                allow_shell_execution=True,
                gateway_url="http://gateway",
                llm_operator_requires_approval=False,
                llm_operator_final_response_mode="simple",
                reliability_mode="off",
                operator_legacy_overrides={
                    "llm_operator_max_validation_repair_attempts": 0,
                    "llm_operator_max_completion_repair_attempts": 0,
                },
            ),
            InMemoryResultStore(),
            gateway_client=gateway,  # type: ignore[arg-type]
        ),
        OutputPipelineOrchestrator(),
    )

    result = runtime.continue_from_trace(
        trace,
        {
            "agent_mode": "llm_operator",
            "workflow_execution_mode": "streaming",
            "llm_operator_final_response_mode": "simple",
        },
    )

    assert "## Streaming Complete" in result
    assert [call["command"] for call in gateway.raw_calls] == ["printf recovered"]
    assert "OperatorFailureContinuationReview" not in llm.schemas
    plan_prompt = next(prompt for prompt in llm.prompts if "Streaming operator mode:" in prompt)
    assert "failed to stat" in plan_prompt
    assert "The prior branch list was used as one branch name." in plan_prompt
    resumed_state = trace.metadata["operator_streaming_state"]
    assert resumed_state["current_index"] == 2
    assert resumed_state["completed_task_ids"] == ["task-1", "task-2"]
    task_2_results = [
        item for item in resumed_state["prior_results"] if item["task_id"] == "task-2"
    ]
    assert [item["status"] for item in task_2_results] == ["error", "success"]
    retry_records = task_2_results[-1]["records"]
    assert retry_records[0]["action_id"].startswith("action-")
    assert retry_records[0]["action_id"] != "action-1"
    assert retry_records[0]["stdout"] == "recovered\n"


