def test_standard_agent_runtime_observation_bypasses_direct_answer(tmp_path: Path) -> None:
    class BranchGateway(FakeOperatorGateway):
        def execute_raw_command(
            self,
            *,
            command: str,
            cwd: str,
            execution_context: dict[str, Any] | None = None,
        ) -> dict[str, Any]:
            self.raw_calls.append(
                {"command": command, "cwd": cwd, "execution_context": dict(execution_context or {})}
            )
            return {"stdout": "V12_caterpillar\n", "stderr": "", "exit_code": 0, "gateway_node": "fake"}

    registry = build_default_registry()
    gateway = BranchGateway()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
        ),
        InMemoryResultStore(),
        gateway_client=gateway,  # type: ignore[arg-type]
    )
    llm = QueueLLM(
        {
            "prompt_type": "simple_question",
            "requires_tools": False,
            "likely_domains": [],
            "risk_level": "low",
            "needs_clarification": False,
            "clarification_question": None,
            "reason": "This looks like a no-tool question.",
            "confidence": 0.85,
        },
        _plan_payload(command="git branch --show-current"),
        _formatter_payload("V12_caterpillar"),
    )
    runtime = AgentRuntime(
        llm,
        registry,
        engine,
        OutputPipelineOrchestrator(),
    )

    result = runtime.handle_request(
        "What is the current git branch? Answer with only the branch name.",
        {"workspace_root": str(tmp_path), "workflow_execution_mode": "full_plan"},
    )

    assert result == "V12_caterpillar"
    assert gateway.raw_calls[0]["command"] == "git branch --show-current"
    assert runtime.last_planning_trace.metadata["agent_mode"] == "standard_operator"
    assert "DirectAnswerProposal" not in llm.schemas
    assert "TaskDecompositionProposal" not in llm.schemas


def test_online_mode_direct_answer_ignores_legacy_enabled_flag(monkeypatch, tmp_path: Path) -> None:
    lookup_queries: list[str] = []

    def fake_lookup(query: str, **_: object) -> OnlineLookupResult:
        lookup_queries.append(query)
        return OnlineLookupResult(
            provider="duck_ai",
            query=query,
            available=True,
            answer_text="Use nvidia-smi --query-gpu=memory.free.",
            source_title="NVIDIA docs",
            source_url="https://docs.nvidia.com/deploy/nvidia-smi/",
            fetched_at="2026-05-15T00:00:00Z",
        )

    monkeypatch.setattr(orchestrator_module, "lookup_online_answer", fake_lookup)
    registry = build_default_registry()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(workspace_root=str(tmp_path), operator_online_mode_enabled=True),
        InMemoryResultStore(),
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
    )
    llm = QueueLLM(
        {
            "prompt_type": "simple_question",
            "requires_tools": False,
            "likely_domains": [],
            "risk_level": "low",
            "needs_clarification": False,
            "clarification_question": None,
            "reason": "This can be answered directly.",
            "confidence": 0.9,
        },
        {
            "answer": "Use nvidia-smi --query-gpu=memory.free.",
            "confidence": 0.9,
            "reason": "Used online context.",
        },
    )
    runtime = AgentRuntime(llm, registry, engine, OutputPipelineOrchestrator())

    result = runtime.handle_request(
        "What nvidia-smi flag reports free GPU memory?",
        {"operator_online_mode_enabled": True, "workspace_root": str(tmp_path)},
    )

    assert result == "Use nvidia-smi --query-gpu=memory.free."
    assert lookup_queries == []
    assert not any("Online lookup context" in prompt for prompt in llm.prompts)
    assert "operator_online_mode_enabled" not in runtime.last_planning_trace.metadata


