def test_operator_cwd_outside_workspace_is_rejected_when_guard_enabled(tmp_path: Path) -> None:
    bad_plan = _plan_payload(cwd=str(tmp_path.parent))
    pipeline = _pipeline(
        tmp_path,
        QueueLLM(
            bad_plan,
            {
                **_repair_reasoning_fields(),
                "corrected_plan": bad_plan,
                "retry_rationale": "Keep the same invalid cwd.",
                "expected_change": "None.",
                "confidence": 0.1,
            },
        ),
        config_overrides={"operator_workspace_cwd_guard_enabled": True},
    )

    try:
        pipeline.propose_and_validate(UserRequest(raw_prompt="run command outside workspace"))
    except Exception as exc:
        errors = getattr(exc, "errors", [])
    else:
        raise AssertionError("Expected operator validation failure")

    assert any(error["error"] == "cwd_outside_workspace" for error in errors)


