def test_operator_may_prompt_streams_through_terminal_without_global_run_in_terminal(
    tmp_path: Path,
) -> None:
    payload = _plan_payload(command="git push origin $(git branch --show-current)")
    payload["actions"][0]["interaction_mode"] = "may_prompt"
    payload["actions"][0]["risk"] = "high"
    gateway = TerminalStreamOperatorGateway()
    llm = QueueLLM(payload, _formatter_payload("pushed"))
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=gateway,  # type: ignore[arg-type]
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            gateway_timeout_seconds=30,
            terminal_session_id="term-test",
            terminal_cwd=str(tmp_path),
            terminal_execution_enabled=False,
        ),
        result_store=InMemoryResultStore(),
    )
    request = UserRequest(raw_prompt="push to origin")

    plan, errors = pipeline.propose_and_validate(request)
