def test_mutating_operator_success_can_request_completion_continuation(tmp_path: Path) -> None:
    plan_payload = _plan_payload(command="printf removed")
    plan_payload["tasks"][0]["semantic_verb"] = "delete"
    plan_payload["actions"][0]["risk"] = "high"
    continuation_payload = _plan_payload(command="printf remove-remaining")
    continuation_payload["tasks"][0]["semantic_verb"] = "delete"
    continuation_payload["actions"][0]["risk"] = "high"
    llm = QueueLLM(
        {
            "decision": "needs_more_actions",
            "continuation_plan": continuation_payload,
            "issues": ["One or more matching targets may remain."],
            "reason": "The execution did not prove that all matching targets are gone.",
            "confidence": 0.82,
        }
    )
    pipeline = _pipeline(tmp_path, llm)

    result = pipeline.execute_approved(
        UserRequest(raw_prompt="remove every matching environment"),
        OperatorPlan.model_validate(plan_payload),
        {"confirmation": True},
    )

    assert result.status == "confirmation_required"
    assert result.metadata["completion_review_pending"] is True
    assert result.execution_records[0].status == "success"
    assert result.plan is not None
    assert result.plan.actions[0].command == "printf remove-remaining"
    assert llm.schemas == ["OperatorCompletionReview"]
    assert "fully satisfied the user's requested end state" in llm.prompts[0]


def _step_validation_runtime(
    tmp_path: Path,
    llm: QueueLLM,
    *,
    enabled: bool = True,
) -> AgentRuntime:
    registry = build_default_registry()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
            llm_operator_step_validation_enabled=enabled,
        ),
        InMemoryResultStore(),
        gateway_client=FakeOperatorGateway(),  # type: ignore[arg-type]
    )
    return AgentRuntime(llm, registry, engine, OutputPipelineOrchestrator())


def _step_validation_inputs(tmp_path: Path) -> tuple[UserRequest, UserRequest, dict[str, Any], dict[str, Any], OperatorPlan, OperatorPipelineResult]:
    plan_payload = _plan_payload(
        command='printf "%s\\n" "$OF_INPUT_TOTAL_SIZE" > "$OF_INPUT_FILE_NAME"',
        cwd=str(tmp_path),
    )
    plan_payload["actions"][0]["inputs"] = {
        "total_size": "2.55GB",
        "file_name": "answer.txt",
    }
    plan_payload["actions"][0]["reason"] = "Save the calculated total size to answer.txt."
    plan = OperatorPlan.model_validate(plan_payload)
    record = OperatorExecutionRecord(
        action_id="action_1",
        task_id="task_1",
        kind="shell_command",
        status="success",
        stdout="",
        stderr="",
        exit_code=0,
        metadata={
            "cwd": str(tmp_path),
            "bound_inputs_preview": {
                "total_size": "2.55GB",
                "file_name": "answer.txt",
            },
            "shell_input_env_names": ["OF_INPUT_TOTAL_SIZE", "OF_INPUT_FILE_NAME"],
        },
    )
    result = OperatorPipelineResult(
        status="success",
        final_response="Saved total size.",
        plan=plan,
        execution_records=[record],
    )
    state = {
        "original_prompt": "list docker images, calculate total size, and save that to file answer.txt",
        "current_index": 2,
        "prior_results": [
            {"task_id": "task_1", "description": "List Docker images", "status": "success", "records": []},
            {"task_id": "task_2", "description": "Calculate total size", "status": "success", "records": []},
        ],
    }
    task = {
        "task_id": "task_3",
        "streaming_step_id": "step-save",
        "description": "Save the calculated total size to a file named answer.txt.",
        "semantic_verb": "save",
        "object_type": "file",
        "constraints": {},
    }
    user_request = UserRequest(raw_prompt=state["original_prompt"], request_id="req-step")
    step_request = UserRequest(
        raw_prompt=task["description"],
        request_id="req-step",
        session_context={
            "operator_streaming_current_task": task,
            "operator_streaming_current_index": 2,
            "operator_streaming_prior_results": {"completed_tasks": state["prior_results"]},
            "operator_mode_label": "Agent",
        },
    )
    return user_request, step_request, state, task, plan, result


def test_streaming_step_validation_accepts_exact_artifact_evidence(tmp_path: Path) -> None:
    (tmp_path / "answer.txt").write_text("2.55GB\n", encoding="utf-8")
    llm = QueueLLM(
        {
            "decision": "accept",
            "satisfied": True,
            "evidence_summary": "answer.txt exists and contains the calculated total.",
            "missing_evidence": [],
            "contract_violations": [],
            "repair_guidance": "",
            "reason": "The exact requested artifact was created with the expected value.",
            "confidence": 0.96,
        }
    )
    runtime = _step_validation_runtime(tmp_path, llm)
    user_request, step_request, state, task, plan, result = _step_validation_inputs(tmp_path)
    trace = PlanningTrace(request_id="req-step", raw_prompt=user_request.raw_prompt)
    sink = InMemoryEventSink()
    observability = build_observability_context(
        "req-step",
        {"observability": {"enabled": True, "debug": True, "sinks": [sink]}},
    )

    validated = runtime._run_streaming_step_validation(
        user_request=user_request,
        step_request=step_request,
        state=state,
        task=task,
        plan=plan,
        result=result,
        context={"workspace_root": str(tmp_path), "llm_operator_step_validation_enabled": True},
        observability=observability,
        trace=trace,
    )

    assert validated.status == "success"
    assert llm.schemas == ["OperatorStepValidationReview"]
    assert "answer.txt" in llm.prompts[0]
    assert "OF_INPUT_FILE_NAME" in llm.prompts[0]
    assert trace.metadata["operator_step_validations"][0]["decision"] == "accept"


def test_streaming_step_validation_blocks_wrong_or_missing_artifact(tmp_path: Path) -> None:
    (tmp_path / "output.txt").write_text("2.55GB\n", encoding="utf-8")
    llm = QueueLLM(
        {
            "decision": "repair",
            "satisfied": False,
            "evidence_summary": "output.txt exists, but answer.txt is missing.",
            "missing_evidence": ["No evidence that answer.txt exists."],
            "contract_violations": ["Wrong artifact path."],
            "repair_guidance": "Write the calculated value to answer.txt and verify that file.",
            "reason": "The requested artifact was not proven.",
            "confidence": 0.94,
        }
    )
    runtime = _step_validation_runtime(tmp_path, llm)
    user_request, step_request, state, task, plan, result = _step_validation_inputs(tmp_path)
    trace = PlanningTrace(request_id="req-step", raw_prompt=user_request.raw_prompt)
    observability = build_observability_context("req-step", {})

    validated = runtime._run_streaming_step_validation(
        user_request=user_request,
        step_request=step_request,
        state=state,
        task=task,
        plan=plan,
        result=result,
        context={"workspace_root": str(tmp_path), "llm_operator_step_validation_enabled": True},
        observability=observability,
        trace=trace,
    )

    assert validated.status == "error"
    assert "Step Validation Blocked" in validated.final_response
    assert "answer.txt" in llm.prompts[0]
    assert trace.metadata["operator_step_validations"][0]["decision"] == "repair"


