def test_step_validation_artifacts_are_scoped_to_current_task(tmp_path: Path) -> None:
    original = "list docker images, calculate total size, and save that to file answer.txt"
    pipeline = _pipeline(tmp_path, QueueLLM())
    request = UserRequest(raw_prompt=original)
    plan = OperatorPlan.model_validate(
        {
            "summary": "Calculate then save.",
            "tasks": [
                {
                    "task_id": "task_1",
                    "goal": "List all Docker images",
                    "semantic_verb": "list",
                    "object_type": "docker.image",
                    "dependencies": [],
                    "reason": "",
                },
                {
                    "task_id": "task_2",
                    "goal": "Calculate the total size of the listed Docker images",
                    "semantic_verb": "calculate",
                    "object_type": "data",
                    "dependencies": ["task_1"],
                    "reason": "",
                },
                {
                    "task_id": "task_3",
                    "goal": "Save the calculated total size to a file named answer.txt",
                    "semantic_verb": "create",
                    "object_type": "filesystem.file",
                    "dependencies": ["task_2"],
                    "reason": "",
                },
            ],
            "actions": [],
            "dependencies": [],
            "expected_outputs": [],
            "assumptions": [],
        }
    )

    list_contract = pipeline._operator_step_validation_contract_for_task(
        request,
        plan.tasks[0],
        index=0,
    )
    calc_contract = pipeline._operator_step_validation_contract_for_task(
        request,
        plan.tasks[1],
        index=1,
    )
    save_contract = pipeline._operator_step_validation_contract_for_task(
        request,
        plan.tasks[2],
        index=2,
    )

    assert "docker.image" not in list_contract.requested_artifacts
    assert list_contract.requested_mutations == []
    assert "answer.txt" not in calc_contract.requested_artifacts
    assert calc_contract.requested_mutations == []
    assert "answer.txt" in save_contract.requested_artifacts


