def test_full_plan_step_validation_uses_all_successful_action_records(tmp_path: Path) -> None:
    class CommitGateway(FakeOperatorGateway):
        def execute_raw_command(
            self,
            *,
            command: str,
            cwd: str,
            execution_context: dict[str, Any] | None = None,
        ) -> dict[str, Any]:
            self.raw_calls.append(
                {"command": command, "cwd": cwd, "execution_context": dict(execution_context or {})}
            )
            if "git commit" in command:
                return {
                    "stdout": "[main abc1234] test commit\n 13 files changed, 20 insertions(+)\n",
                    "stderr": "",
                    "exit_code": 0,
                    "gateway_node": "fake",
                }
            return {"stdout": "", "stderr": "", "exit_code": 0, "gateway_node": "fake"}

    plan_payload = _plan_payload(command="git add --all", cwd=str(tmp_path))
    plan_payload["summary"] = "Stage and commit changes."
    plan_payload["tasks"] = [
        {
            "task_id": "task_1",
            "goal": "Stage all changes and commit them",
            "semantic_verb": "commit",
            "object_type": "repository",
            "dependencies": [],
            "reason": "The user requested staging and committing changes.",
        },
        {
            "task_id": "task_2",
            "goal": "Commit the staged changes",
            "semantic_verb": "commit",
            "object_type": "repository",
            "dependencies": ["task_1"],
            "reason": "The staged changes need a commit.",
        },
    ]
    plan_payload["actions"] = [
        plan_payload["actions"][0],
        {
            **plan_payload["actions"][0],
            "action_id": "action_2",
            "task_id": "task_2",
            "command": "git commit -m test",
            "risk": "high",
            "reason": "Commit staged changes.",
            "depends_on": ["action_1"],
        },
    ]
    plan_payload["actions"][0]["task_id"] = "task_1"
    plan_payload["actions"][0]["risk"] = "medium"
    llm = QueueLLM(
        {
            "decision": "continue_with_more_evidence",
            "satisfied": False,
            "evidence_summary": "The staging action succeeded.",
            "missing_evidence": ["The commit action is not confirmed in the execution records."],
            "contract_violations": [],
            "repair_guidance": "Confirm that the commit action also executed.",
            "reason": "The commit action is not confirmed in the execution records.",
            "confidence": 0.8,
        },
        {
            "decision": "accept",
            "satisfied": True,
            "evidence_summary": "The commit action succeeded.",
            "missing_evidence": [],
            "contract_violations": [],
            "repair_guidance": "",
            "reason": "The execution records satisfy the commit step.",
            "confidence": 0.95,
        },
    )
    pipeline = _pipeline(
        tmp_path,
        llm,
        gateway=CommitGateway(),
        config_overrides={
            "llm_operator_step_validation_enabled": True,
            "llm_operator_final_response_mode": "simple",
            "llm_operator_max_completion_repair_attempts": 0,
        },
    )

    result = pipeline.execute_approved(
        UserRequest(raw_prompt='stage all and commit with message "test"'),
        OperatorPlan.model_validate(plan_payload),
        {"confirmation": True},
    )

    assert result.status == "success"
    assert llm.schemas == ["OperatorStepValidationReview", "OperatorStepValidationReview"]
    assert "git commit -m test" in llm.prompts[0]
    assert "plan_action_completion" in llm.prompts[0]
    assert '"missing_action_ids": []' in llm.prompts[0]


