def test_agent_runtime_operator_mode_pauses_mutating_plan_for_approval(tmp_path: Path) -> None:
    registry = build_default_registry()
    gateway = FakeOperatorGateway()
    store = InMemoryResultStore()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
        ),
        store,
        gateway_client=gateway,  # type: ignore[arg-type]
    )
    runtime = AgentRuntime(
        QueueLLM(_plan_payload(command="printf hello > report.txt")),
        registry,
        engine,
        OutputPipelineOrchestrator(),
    )

    first = runtime.handle_request(
        "write report",
        {
            "agent_mode": "llm_operator",
            "workspace_root": str(tmp_path),
            "workflow_execution_mode": "full_plan",
        },
    )
    sink = InMemoryEventSink()
    profiler = RuntimeProfiler(runtime.last_planning_trace.request_id)
    approved = runtime.replay_from_trace(
        runtime.last_planning_trace,
        {
            "confirmation": True,
            "workspace_root": str(tmp_path),
            "runtime_profiler": profiler,
            "observability": {
                "enabled": True,
                "debug": True,
                "sinks": [sink],
            },
        },
    )

    assert first.startswith("## Confirmation Required")
    assert gateway.raw_calls
    assert "Stdout:" not in approved
    assert runtime.last_profile_summary is not None
    assert runtime.last_profile_summary["final_status"] == "success"
    profile_events = [event for event in sink.events if event.event_type == "profiling.completed"]
    assert profile_events
    runtime_profile = profile_events[-1].details["runtime_profile"]
    assert isinstance(runtime_profile["stage_timings"], list)
    assert "llm_retry_groups" in runtime_profile
    assert runtime_profile["final_status"] == "success"


