def test_streaming_confirmation_replay_does_not_completion_continue_later_steps(
    tmp_path: Path,
) -> None:
    class CompletionReviewTrapLLM(QueueLLM):
        def complete_json(self, prompt: str, schema: dict[str, Any]) -> dict[str, Any]:
            title = str(schema.get("title") or "")
            if title == "OperatorCompletionReview":
                return {
                    "decision": "needs_more_actions",
                    "continuation_plan": _plan_payload(
                        "git push origin HEAD",
                        cwd=str(tmp_path),
                    ),
                    "issues": ["The full original request still includes a later push step."],
                    "reason": "This must not run inside a streaming step replay.",
                    "confidence": 0.99,
                }
            return super().complete_json(prompt, schema)

    stage_plan_payload = _plan_payload("git add --all", cwd=str(tmp_path))
    stage_plan_payload["summary"] = "Stage all changes."
    stage_plan_payload["tasks"][0].update(
        {
            "task_id": "task-1",
            "goal": "Stage all changes",
            "semantic_verb": "execute",
            "object_type": "git",
        }
    )
    stage_plan_payload["actions"][0].update(
        {
            "action_id": "action-stage",
            "task_id": "task-1",
            "risk": "medium",
            "reason": "Stage all changes.",
        }
    )
    commit_plan_payload = _plan_payload(
        'git commit -m "ux changes and bug fixes"',
        cwd=str(tmp_path),
    )
    commit_plan_payload["summary"] = "Commit staged changes."
    commit_plan_payload["tasks"][0].update(
        {
            "task_id": "task-2",
            "goal": "Commit with description 'ux changes and bug fixes'",
            "semantic_verb": "execute",
            "object_type": "git",
            "dependencies": ["task-1"],
        }
    )
    commit_plan_payload["actions"][0].update(
        {
            "action_id": "action-commit",
            "task_id": "task-2",
            "risk": "medium",
            "reason": "Commit the staged changes.",
        }
    )
    streaming_state = {
        "original_prompt": 'stage all changes and commit with description "ux changes and bug fixes" and push to origin',
        "agent_mode": "standard_operator",
        "global_constraints": {},
        "classification": {
            "likely_domains": ["operator"],
            "prompt_type": "simple_tool_task",
            "requires_tools": True,
            "risk_level": "high",
        },
        "tasks": [
            {
                "task_id": "task-1",
                "description": "Stage all changes",
                "semantic_verb": "execute",
                "object_type": "git",
                "dependencies": [],
                "constraints": {},
                "requires_confirmation": True,
                "risk_level": "medium",
            },
            {
                "task_id": "task-2",
                "description": "Commit with description 'ux changes and bug fixes'",
                "semantic_verb": "execute",
                "object_type": "git",
                "dependencies": ["task-1"],
                "constraints": {},
                "requires_confirmation": True,
                "risk_level": "medium",
            },
            {
                "task_id": "task-3",
                "description": "Push to origin",
                "semantic_verb": "execute",
                "object_type": "git",
                "dependencies": ["task-2"],
                "constraints": {},
                "requires_confirmation": True,
                "risk_level": "high",
            },
        ],
        "current_index": 0,
        "completed_task_ids": [],
        "prior_results": [],
    }
    trace = PlanningTrace(
        request_id="req-streaming-git-confirmation",
        raw_prompt=streaming_state["original_prompt"],
        metadata={
            "agent_mode": "standard_operator",
            "operator_execution_mode": "streaming",
            "operator_plan": stage_plan_payload,
            "operator_streaming_state": streaming_state,
        },
    )
    registry = build_default_registry()
    gateway = FakeOperatorGateway()
    engine = ExecutionEngine(
        registry,
        RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            gateway_url="http://gateway",
        ),
        InMemoryResultStore(),
        gateway_client=gateway,  # type: ignore[arg-type]
    )
    llm = CompletionReviewTrapLLM(commit_plan_payload)
    runtime = AgentRuntime(llm, registry, engine, OutputPipelineOrchestrator())

    result = runtime.replay_from_trace(
        trace,
        {
            "workspace_root": str(tmp_path),
            "operator_execution_mode": "streaming",
            "llm_operator_plan_review_enabled": False,
            "llm_operator_self_brief_mode": "off",
            "llm_operator_final_response_mode": "simple",
            "llm_operator_max_completion_repair_attempts": 1,
            "confirmation": True,
        },
    )

    assert "Confirmation Required" in result
    assert 'git commit -m "ux changes and bug fixes"' in result
    assert "git push origin HEAD" not in result
    assert [call["command"] for call in gateway.raw_calls] == ["git add --all"]
    assert "OperatorCompletionReview" not in llm.schemas
    assert trace.metadata["operator_streaming_state"]["current_index"] == 1
    assert trace.metadata["operator_streaming_state"]["completed_task_ids"] == ["task-1"]


