def test_streaming_operator_rejects_later_git_push_inside_commit_step(tmp_path: Path) -> None:
    mixed_plan = _plan_payload(command='git commit -m "fix copy button position"', cwd=str(tmp_path))
    mixed_plan["summary"] = "Commit and push changes."
    mixed_plan["tasks"][0].update(
        {
            "task_id": "task-2",
            "goal": "Commit changes with message 'fix copy button position'",
            "semantic_verb": "execute",
            "object_type": "git",
            "dependencies": ["task-1"],
        }
    )
    mixed_plan["actions"][0].update(
        {
            "action_id": "action-commit",
            "task_id": "task-2",
            "command": 'git commit -m "fix copy button position"',
            "risk": "medium",
        }
    )
    mixed_plan["actions"].append(
        {
            "action_id": "action-push",
            "task_id": "task-2",
            "kind": "shell_command",
            "command": "git push",
            "cwd": str(tmp_path),
            "inputs": {},
            "declared_output_shape": "text",
            "risk": "high",
            "timeout_seconds": 5,
            "reason": "Push the committed changes to the remote repository.",
            "depends_on": ["action-commit"],
        }
    )
    repaired_plan = _plan_payload(
        command='git commit -m "fix copy button position"',
        cwd=str(tmp_path),
    )
    repaired_plan["summary"] = "Commit changes."
    repaired_plan["tasks"][0].update(
        {
            "task_id": "task-2",
            "goal": "Commit changes with message 'fix copy button position'",
            "semantic_verb": "execute",
            "object_type": "git",
            "dependencies": ["task-1"],
        }
    )
    repaired_plan["actions"][0].update(
        {
            "action_id": "action-commit",
            "task_id": "task-2",
            "command": 'git commit -m "fix copy button position"',
            "risk": "medium",
        }
    )
    llm = QueueLLM(
        mixed_plan,
        {
            **_repair_reasoning_fields(),
            "corrected_plan": repaired_plan,
            "retry_rationale": "Streaming step 2 is commit-only; push belongs to step 3.",
            "expected_change": "The repaired plan removes git push from the commit step.",
            "confidence": 0.95,
        },
    )
    pipeline = _pipeline(
        tmp_path,
        llm,
        config_overrides={
            "llm_operator_plan_review_enabled": False,
            "llm_operator_self_brief_mode": "off",
            "llm_operator_max_validation_repair_attempts": 1,
        },
    )
    request = UserRequest(
        raw_prompt=(
            "Original request: stage all changes and commit using description - "
            '"fix copy button position" and push changes\n'
            "Streaming step 2 of 3: Commit changes with message 'fix copy button position'"
        ),
        session_context={
            "operator_streaming_current_index": 1,
            "operator_streaming_current_task": {
                "task_id": "task-2",
                "description": "Commit changes with message 'fix copy button position'",
                "semantic_verb": "execute",
                "object_type": "git",
                "requires_confirmation": True,
                "risk_level": "medium",
            },
            "operator_streaming_tasks": [
                {
                    "task_id": "task-1",
                    "description": "Stage all changes",
                    "semantic_verb": "execute",
                    "object_type": "git",
                },
                {
                    "task_id": "task-2",
                    "description": "Commit changes with message 'fix copy button position'",
                    "semantic_verb": "execute",
                    "object_type": "git",
                },
                {
                    "task_id": "task-3",
                    "description": "Push changes to remote repository",
                    "semantic_verb": "execute",
                    "object_type": "git",
                    "requires_confirmation": True,
                    "risk_level": "high",
                },
            ],
        },
    )

    plan, errors = pipeline.propose_and_validate(request)

    assert errors == []
    assert [action.command for action in plan.actions] == ['git commit -m "fix copy button position"']
    prompts = "\n".join(llm.prompts)
    assert "streaming_future_step_action" in prompts
    assert "current decomposed task is the only executable scope" in prompts
    assert "Later decomposed tasks reserved for future calls" in prompts
    assert "push" in prompts


def test_streaming_step_prompt_prioritizes_current_step_scope() -> None:
    state = {
        "original_prompt": (
            "find docker compose files, filter docker-compose.yml files, "
            "show running containers, then compose down"
        ),
        "current_index": 1,
        "tasks": [
            {"task_id": "task-1", "description": "Find all docker compose files"},
            {"task_id": "task-2", "description": "Filter only docker-compose.yml files"},
            {"task_id": "task-3", "description": "Show running containers"},
            {"task_id": "task-4", "description": "Stop compose services"},
        ],
    }

    prompt = AgentRuntime._streaming_step_prompt(  # type: ignore[arg-type]
        object(),
        state,
        state["tasks"][1],
    )

    assert prompt.startswith("Streaming step 2 of 4: Filter only docker-compose.yml files")
    assert "This step is the only executable scope" in prompt
    assert "produce only that narrowed result" in prompt
    assert "Original request background:" in prompt
    assert prompt.index("Streaming step 2") < prompt.index("Original request background:")
    assert (
        "Later steps reserved for future calls: Show running containers | Stop compose services"
        in prompt
    )


def test_operator_streaming_plan_prompt_reserves_future_tasks() -> None:
    request = UserRequest(
        raw_prompt=(
            "Streaming step 2 of 4: Filter only docker-compose.yml files\n"
            "Original request background: find compose files, show running containers, compose down"
        ),
        session_context={
            "operator_streaming_current_index": 1,
            "operator_streaming_current_task": {
                "task_id": "task-2",
                "description": "Filter only docker-compose.yml files",
                "semantic_verb": "filter",
                "object_type": "file",
                "risk_level": "low",
                "requires_confirmation": False,
            },
            "operator_streaming_tasks": [
                {
                    "task_id": "task-1",
                    "description": "Find all docker compose files",
                    "semantic_verb": "search",
                    "object_type": "file",
                },
                {
                    "task_id": "task-2",
                    "description": "Filter only docker-compose.yml files",
                    "semantic_verb": "filter",
                    "object_type": "file",
                },
                {
                    "task_id": "task-3",
                    "description": "Show running containers",
                    "semantic_verb": "read",
                    "object_type": "docker.container",
                },
                {
                    "task_id": "task-4",
                    "description": "Stop compose services",
                    "semantic_verb": "execute",
                    "object_type": "docker.compose",
                },
            ],
        },
    )

    prompt = build_operator_plan_prompt(request)

    assert "current decomposed task is the only executable scope" in prompt
    assert "Treat the original full request as background context only" in prompt
    assert "For filter/select/sort/transform steps" in prompt
    assert "Later decomposed tasks reserved for future calls" in prompt
    assert "Show running containers" in prompt
    assert "Stop compose services" in prompt
    assert "Do not author actions for these later tasks" in prompt


def test_operator_prompts_include_target_gateway_platform_context() -> None:
    request = UserRequest(
        raw_prompt="copy the latest screenshot to the clipboard",
        session_context={
            "gateway_id": "gw-mac",
            "gateway_node": "studio-mac",
            "gateway_url": "http://10.0.0.9:8787",
            "gateway_platform": "macos",
            "gateway_platform_label": "macOS",
            "gateway_platform_version": "15.5",
            "gateway_architecture": "arm64",
            "gateway_shell": "/bin/bash",
            "gateway_command_profile": "posix-bash-macos",
            "gateway_capability_tags": ["exec", "python", "terminal", "macos_cli"],
        },
    )

    plan_prompt = build_operator_plan_prompt(request)
    repair_prompt = build_operator_repair_prompt(
        request,
        OperatorPlan.model_validate(_plan_payload(command="xclip -selection clipboard screenshot.png")),
        [
            OperatorExecutionRecord(
                action_id="action_1",
                task_id="task_1",
                kind="shell_command",
                status="error",
                stderr="xclip: command not found",
                exit_code=127,
                error="command not found: xclip",
            )
        ],
    )

    for prompt in (plan_prompt, repair_prompt):
        assert "Target gateway context" in prompt
        assert '"gateway_platform": "macos"' in prompt
        assert '"gateway_platform_label": "macOS"' in prompt
        assert '"gateway_shell": "/bin/bash"' in prompt
        assert "posix-bash-macos" in prompt
        assert "osascript" in prompt
        assert "pbcopy" in prompt
        assert "screencapture" in prompt
        assert "Do not assume GNU Linux-only flags" in prompt


