def test_guided_deliberation_reviews_execution_evidence(tmp_path: Path) -> None:
    llm = QueueLLM(_evidence_satisfaction_payload())
    plan = OperatorPlan.model_validate(_plan_payload("printf hello", cwd=str(tmp_path)))
    records = [
        OperatorExecutionRecord(
            action_id="action_1",
            task_id="task_1",
            kind="shell_command",
            status="success",
            stdout="hello",
            stderr="",
            exit_code=0,
        )
    ]
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=FakeOperatorGateway(),
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            guided_deliberation_mode="always",
        ),
        result_store=InMemoryResultStore(),
    )

    review = pipeline._complete_evidence_satisfaction_review(
        UserRequest(raw_prompt="print hello", session_context={}),
        plan,
        records,
        observability=None,
    )

    assert review is not None
    assert review.decision == "satisfied"
    assert llm.schemas == ["EvidenceSatisfactionReview"]


def test_guided_deliberation_evidence_rejects_mutating_continuation(tmp_path: Path) -> None:
    continuation_plan = _plan_payload("touch should_not_exist", cwd=str(tmp_path))
    llm = QueueLLM(_evidence_satisfaction_payload("continue_required", continuation_plan))
    gateway = FakeOperatorGateway()
    plan = OperatorPlan.model_validate(_plan_payload("printf ok", cwd=str(tmp_path)))
    pipeline = LLMOperatorPipeline(
        llm_client=llm,
        gateway_client=gateway,
        config=RuntimeConfig(
            workspace_root=str(tmp_path),
            allow_shell_execution=True,
            guided_deliberation_mode="always",
            llm_operator_final_response_mode="simple",
            llm_operator_max_completion_repair_attempts=1,
        ),
        result_store=InMemoryResultStore(),
    )

    result = pipeline.execute_approved(
        UserRequest(raw_prompt="print ok", session_context={}),
        plan,
        {"confirmation": True},
    )

    assert result.status == "success"
    assert [call["command"] for call in gateway.raw_calls] == ["printf ok"]
    assert not (tmp_path / "should_not_exist").exists()
    assert llm.schemas == ["EvidenceSatisfactionReview"]
